      "path": "packages/dsh-notifier/src/index.ts",
      "content": "/**\n * 宿主端组合根：收窄宿主上下文、按依赖顺序装配各域（`upgrade` 最先因其动磁盘、`api` 最后因其读现值）、卸载逆序释放。\n * 交付的是能力对象而非装配期快照——设置是活的，快照看起来与实时读取一模一样。\n */\nimport type { Context } from \"@deepseek-ai/cordis\";\nimport type {} from \"@deepseek-ai/dsh-agent\";\nimport type {\n  LOCALE_SETTINGS_NAMESPACE as HostLocaleNamespace,\n  LOCALE_PREFERENCE_FIELD as HostLocalePreferenceField,\n} from \"@deepseek-ai/dsh-client-locale\";\nimport type {} from \"@deepseek-ai/dsh-session\";\nimport type {} from \"@deepseek-ai/dsh-settings\";\nimport type {} from \"@deepseek-ai/dsh-user-approval\";\nimport type {} from \"@deepseek-ai/dsh-user-questions\";\nimport type { WebRoute } from \"@deepseek-ai/dsh-host-webserver\";\nimport * as apiApi from \"./server/api/interface.ts\";\nimport * as channelsApi from \"./server/channels/interface.ts\";\nimport * as configApi from \"./server/config/interface.ts\";\nimport * as eventsApi from \"./server/events/interface.ts\";\nimport type { AgentRegistryPort, HostEventPort } from \"./server/events/interface.ts\";\nimport * as pipelineApi from \"./server/pipeline/interface.ts\";\nimport type { OutgoingFrame } from \"./server/pipeline/interface.ts\";\nimport type { LegacySettingsFace } from \"./server/upgrade/deps.ts\";\nimport type { ExposePort } from \"./server/sdk/deps.ts\";\nimport * as sdkApi from \"./server/sdk/interface.ts\";\nimport type { NotifierService } from \"./server/sdk/interface.ts\";\nimport type { LoggerPort, NotificationLocale } from \"./server/shared/interface.ts\";\nimport * as storesApi from \"./server/stores/interface.ts\";\nimport { installUpgrade, releaseUpgrade } from \"./server/upgrade/interface.ts\";\nimport {\n  admitLongLivedRequest,\n  bindPeerLifecycle,\n  liveConnectionAdmission,\n  liveConnectionPeerAdmission,\n  routeFenceRejection,\n} from \"../../../shared/host-utils.js\";\nimport { createDisposerStack, type DisposerStack } from \"./shared/interface.ts\";\n\n/**\n * 对外服务面类型：消费方要写 `const n: NotifierService = ctx[\"wingsky.notifier\"]` 就得能命名它，\n * 它同时是下面声明合并的载荷。\n */\nexport type { NotifierService } from \"./server/sdk/interface.ts\";\n\n/** 宿主 settings 服务的名字。它是宿主的知识，不是本插件的 ABI。 */\nconst SETTINGS_SERVICE = \"settings\";\n\n/** 这两个字面量归官方 locale 契约所有；类型锚让上游改名或改字段时编译期直接暴露。 */\nconst LOCALE_NAMESPACE: typeof HostLocaleNamespace = \"locale\";\nconst LOCALE_PREFERENCE_FIELD: typeof HostLocalePreferenceField = \"preference\";\n\n/** 稳定的 cordis 插件名。 */\nexport const name = \"notifier\";\n\n/**\n * 依赖的宿主服务。`settings` 是**必需**依赖而不是可选探测：0.2.3 把配置存在它那里，装配期要读一次存量。\n * 声明成依赖之后，宿主保证服务就绪才装配本插件——顺序由框架保证，比「先试一次、再监听晚到的」可靠。\n */\nexport const inject = [\"webServer\", SETTINGS_SERVICE];\n\n/**\n * 组合层入口配置（插件挂载点传入）。只有总开关：设置项全部住在本插件自己的配置文件里，\n * 这里再开一层默认值只会让人以为某处配过什么，而它永远是空的。\n */\nexport interface NotifierApplyConfig {\n  /** 总开关；`false` 时一律不投递。不落盘、不进设置层。 */\n  enabled?: boolean;\n}\n\n/**\n * 挂载 dsh-notifier。**异步**：升级域的存储迁移是异步链，调用方（宿主或测试）必须 `await`——\n * 不等待就等于让各域在迁移跑完之前去读磁盘，读到的是被搬走一半的旧形态。\n */\nexport async function apply(ctx: Context, config: NotifierApplyConfig = {}): Promise<void> {\n  const host = bindHost(ctx);\n  const stack = createDisposerStack();\n  try {\n    await assemble(host, config, stack);\n  } finally {\n    // 登记点留在采集之后：cordis 按 LIFO 释放 effect，提前登记会让整条栈在服务面已撤之后\n    // 才释放各域（api 域在别人已放开的入参上继续服务）。用 finally 而不是顺序执行，是为了\n    // 装配中途抛错时已采集的 teardown 也有释放点——原先那种「拿返回值去登记」的写法一抛错\n    // 就整条链一个都没登记。\n    stack.attach(ctx, \"dsh-notifier\");\n  }\n}\n\n/**\n * 宿主事件默认按 fiber 作用域过滤，通知插件必须看到所有会话与 agent，故每条订阅都要带它。\n * 漏掉的表现是「有些会话不通知」，且只在多会话下出现——单会话调试永远复现不了。\n */\nconst GLOBAL_LISTEN = { global: true } as const;\n\n/**\n * 对外名字的声明合并。必须写在包入口：`declare module` 是全局增强，入口声明面不可达时\n * `lib/index.d.ts` 里就没有它（`pack:check` 的「声明合并可达性」判据盯这条）；键引用 sdk 域的\n * 常量，服务名只留一个物理定义——抄一份字面量同样能编译，改名漏改时只会在运行时的另一头暴露。\n */\ndeclare module \"@deepseek-ai/cordis\" {\n  interface Context {\n    /** 通知中心服务面：兄弟插件经它登记自己的通知种类、发送通知。 */\n    [sdkApi.NOTIFIER_SERVICE]: NotifierService;\n  }\n}\n\n/**\n * 帧总线：生产端只给 `emit`（裁决管线），消费端只给 `onFrame`（浏览器出口），类型就是围栏。\n * 它是组合根的本地设施而不是宿主事件总线上的事件——总线上的名字是公共面，谁都能收发。\n * 遍历前先取快照：帧是 fire-and-forget 的旁路，回调里退订不该打断本轮其余订阅者。\n */\nclass FrameBus {\n  private readonly handlers = new Set<(payload: OutgoingFrame) => void>();\n\n  emit(payload: OutgoingFrame): void {\n    for (const handler of [...this.handlers]) handler(payload);\n  }\n\n  onFrame(handler: (payload: OutgoingFrame) => void): () => void {\n    this.handlers.add(handler);\n    return () => {\n      this.handlers.delete(handler);\n    };\n  }\n}\n\n/** 组合根用到的宿主面：域拿到的是能力，不是上下文。 */\ninterface HostPort {\n  readonly logger: LoggerPort;\n  /** 官方 connection 的短请求围栏与长连接 Peer 生命周期能力。 */\n  readonly remote: Parameters<typeof apiApi.installApi>[0][\"remote\"];\n  /** 帧总线：帧经它从裁决管线走到浏览器出口。 */\n  readonly frames: FrameBus;\n  /** 宿主路由注册口：只有组合根够得着 `ctx.webServer`。 */\n  readonly register: (route: WebRoute) => () => void;\n  readonly events: HostEventPort;\n  /** 宿主 agent 注册表：子代理归属判定要它。 */\n  readonly agents: AgentRegistryPort;\n  /**\n   * 宿主 settings 服务：0.2.3 把配置存在那里，新架构搬走后仍需用它作低优先级兜底。\n   * 只声明本域要用的 `describe`——正式历史来源由 upgrade 域直接读取 DSH_HOME 双文件。\n   */\n  readonly legacySettings: LegacySettingsFace;\n  /** 宿主出口：把服务面挂上上下文。服务名是 sdk 域的 ABI，组合根不参与命名。 */\n  readonly expose: ExposePort;\n  /** DSH 当前显式语言；每次调用现读，供各域在生成通知时选择产品文案。 */\n  readonly readLocale: () => NotificationLocale;\n}\n\nfunction bindHost(ctx: Context): HostPort {\n  /**\n   * 把本插件的处理收进一个「绝不向宿主抛错」的壳里：本插件在宿主事件链上只是旁观者，\n   * 自己出问题不该影响别人的流程。审批与提问这两条是 waterfall，抛出去会让 `next()`\n   * 不被调用，症状是「审批框不弹了」，与本插件毫无字面关联。\n   */\n  const guard = (run: () => void): void => {\n    try {\n      run();\n    } catch (cause) {\n      // 不静默：这里是唯一还知道发生了什么的地方，吞掉之后「通知不工作」会变成查不出原因的现象。\n      const reason = cause instanceof Error ? cause.message : String(cause);\n      ctx.logger.warn(`dsh-notifier: 宿主事件处理失败 —— ${reason}`);\n    }\n  };\n\n  const remoteAdmission = liveConnectionAdmission(ctx);\n  const remotePeerAdmission = liveConnectionPeerAdmission(ctx);\n\n  return {\n    logger: ctx.logger,\n    remote: {\n      fence: (req) => routeFenceRejection(req, { remoteAdmission }),\n      admitStream: (req) => admitLongLivedRequest(req, { remotePeerAdmission }),\n      bindPeer: bindPeerLifecycle,\n    },\n    frames: new FrameBus(),\n    // 依赖已由 `inject` 声明，服务就绪才轮到本插件装配：这里直接取用，没有探测、也没有迟到分支。\n    legacySettings: ctx.settings,\n    register: (route) => ctx.webServer.register(route),\n    // 名字取自 sdk 域（ABI 的定义处）。显式类型参数是道保险：谁把那里退回硬编码字面量，\n    // 少了它就静默失败——`ctx.provide` 的 `(name: string, value?: any)` 重载会兜住任意字符串。\n    expose: {\n      provide: (service) =>\n        ctx.provide<typeof sdkApi.NOTIFIER_SERVICE>(sdkApi.NOTIFIER_SERVICE, service),\n    },\n    readLocale: () => {\n      const locale = ctx.settings\n        .describe()\n        .find((descriptor) => descriptor.ns === LOCALE_NAMESPACE)?.value;\n      if (typeof locale !== \"object\" || locale === null) return \"zh\";\n      const preference = (locale as Record<string, unknown>)[LOCALE_PREFERENCE_FIELD];\n      return preference === \"en\" ? \"en\" : \"zh\";\n    },\n    events: {\n      // 审批事件是 waterfall：本插件只旁观，转发之后必须 next()，漏掉就等于替所有人否决了\n      // 这次审批，症状是「审批不弹了」。prepend 让本监听器排在链前——前面的监听器不调\n      // next() 时，这次审批会对本插件彻底不可见。\n      onApprovalRequest: (handler) =>\n        ctx.on(\n          \"approval/request\",\n          (request, next) => {\n            guard(() => handler(request));\n            return next();\n          },\n          { global: true, prepend: true },\n        ),\n      // 与审批同构的第二个 waterfall：同样只旁观、同样必须把判定交还，漏 next() 的症状是\n      // 「提问不弹了」。\n      onUserQuestion: (handler) =>\n        ctx.on(\n          \"user-questions/request\",\n          (request, next) => {\n            guard(() => handler(request));\n            return next();\n          },\n          { global: true, prepend: true },\n        ),\n      onSessionEvent: (handler) =>\n        ctx.on(\n          \"session/event\",\n          (session, event) => {\n            guard(() => handler(session.id, event));\n          },\n          GLOBAL_LISTEN,\n        ),\n      // agent 四个事件把官方载荷**原样**转过去：拆成 id 等于替域决定「哪些字段有用」，\n      // 而那个决定正是 events 域该做的判断。\n      onAgentStatus: (handler) =>\n        ctx.on(\n          \"agent/status\",\n          (payload) => {\n            guard(() => handler(payload));\n          },\n          GLOBAL_LISTEN,\n        ),\n      onAgentDisposed: (handler) =>\n        ctx.on(\n          \"agent/disposed\",\n          (payload) => {\n            guard(() => handler(payload));\n          },\n          GLOBAL_LISTEN,\n        ),\n      onAgentTurnStopping: (handler) =>\n        ctx.on(\n          \"agent/turn-stopping\",\n          (payload) => {\n            guard(() => handler(payload));\n          },\n          GLOBAL_LISTEN,\n        ),\n      // 唯一的例外是错误原文：官方那边是宽类型，在这里做唯一一次收窄，域内不出现宽类型。\n      onAgentError: (handler) =>\n        ctx.on(\n          \"agent/error\",\n          (payload) => {\n            const failure = payload.error;\n            const reason = failure instanceof Error ? failure.message : String(failure);\n            guard(() => handler({ ...payload, error: reason }));\n          },\n          GLOBAL_LISTEN,\n        ),\n    },\n    // 宿主 agent 注册表：子代理归属判定的第二个信号。查不到与查得到分开报，怎么理解是域的事。\n    agents: {\n      lookup: (id) => {\n        const agent = ctx.get(\"agents\", false)?.get(id);\n        return agent === undefined ? { found: false } : { found: true, agent };\n      },\n      isOwnedBy: (id, owner) => ctx.get(\"agents\", false)?.isOwnedBy(id, owner) === true,\n    },\n  };\n}\n\n/**\n * 装配：按依赖顺序接上各域，把释放点登记进 `stack`。每步入参都来自上一步的产出或 `host`，\n * 顺序错了就是运行期空值。异步是因为第 1 步的升级链是异步的——不 `await` 它，后面的域就都\n * 读着迁移中的磁盘跑起来了。\n */\nasync function assemble(\n  host: HostPort,\n  config: NotifierApplyConfig,\n  stack: DisposerStack,\n): Promise<void> {\n  // 0. 音频临时目录的释放面：通道域没有装配步骤，但临时目录必须有人收。放在链首 = 逆序释放时\n  //    最后执行——卸载瞬间若还有一笔自播在读那个文件，先删目录会让它复现「spawn 后立即 unlink」\n  //    的失败（实测播放器报 42B 的「打不开」）。\n  stack.own(channelsApi.releaseSoundTemps);\n\n  // 1. 存储与配置形态迁移：动的是磁盘（存储三个文件 + 配置文件），必须早于任何读文件的域。\n  //    存量配置由 settings 的显式依赖保证在装配期可读；链本身是异步的，故 await 到跑完为止。\n  //\n  //    装配前先复位单例标记：apply 在同一进程里会被多次调用（宿主重载插件），而 upgrade 域的标记\n  //    是进程级的；不先复位，第二次装配会在链跑之前就撞上「只能装配一次」。链本身幂等（归档名固定、\n  //    目标存在即不覆盖），重跑不累积。真正的双重装配仍由 installUpgrade 自己的标记在直接调用面上兜住。\n  releaseUpgrade();\n  await installUpgrade({ logger: host.logger, legacySettings: host.legacySettings });\n  stack.own(releaseUpgrade);\n\n  // 1. 设置：读面在装配返回时即可用，后续各域不必等加载。\n  configApi.installConfig({ logger: host.logger });\n  stack.own(configApi.releaseConfig);\n\n  // 2. 存储：保留天数由它自己按需读设置，不在这里替它取值。\n  storesApi.installStores({ logger: host.logger, config: configApi });\n  stack.own(storesApi.releaseStores);\n\n  // 3. 裁决管线：递的是提供方的命名空间对象（消费方用 Pick 收窄），将来多用一样能力不用改这行。\n  pipelineApi.installPipeline({\n    enabled: config.enabled !== false,\n    frames: host.frames,\n    logger: host.logger,\n    config: configApi,\n    stores: storesApi,\n    channels: channelsApi,\n  });\n  stack.own(pipelineApi.releasePipeline);\n\n  // 4. 事件：请求一律产出，去留由裁决层决定——开关会在本域看不见的地方被改。\n  eventsApi.installEvents({\n    events: host.events,\n    agents: host.agents,\n    logger: host.logger,\n    pipeline: pipelineApi,\n    readLocale: host.readLocale,\n  });\n  stack.own(eventsApi.releaseEvents);\n\n  // 5. 对外 ABI：服务面自己不依赖任何后装的域，但 api 域要读它的种类清单，故排在 api 之前。\n  sdkApi.installSdk({\n    expose: host.expose,\n    config: configApi,\n    pipeline: pipelineApi,\n    readLocale: host.readLocale,\n  });\n  stack.own(sdkApi.releaseSdk);\n\n  // 6. 浏览器出口：最后装——它读各域的现值，装早了页面第一次请求就会拿到半成品。\n  apiApi.installApi({\n    register: host.register,\n    frames: host.frames,\n    logger: host.logger,\n    remote: host.remote,\n    config: configApi,\n    stores: storesApi,\n    pipeline: pipelineApi,\n    kinds: sdkApi,\n    channels: channelsApi,\n    readLocale: host.readLocale,\n  });\n  stack.own(apiApi.releaseApi);\n}\n"
    },
    {
      "path": "packages/dsh-notifier/src/server/api/impl/route/index.ts",
      "content": "/**\n * api 域路由块：注册端点并给每条请求套上围栏——回环围栏（非回环一律 403，必须用共享层默认参数：放行 `no-cors` 的开关\n * 只给资源伺服路由）、方法围栏（方法不在表里给 405 而不是 404）、异常收口（漏出去的异常留下的不是错误页，是一个挂住的连接）。\n */\nimport type { ServerResponse } from \"node:http\";\nimport { REFUSAL_CODES } from \"../../../../shared/interface.ts\";\nimport type { RefusalCode } from \"../../../../shared/interface.ts\";\nimport type { LoggerPort, RegisterRoute, RemoteAccessPort } from \"../../deps.ts\";\nimport type { Endpoint, HttpMethod } from \"./type.ts\";\n\n/**\n * 写一个 JSON 响应。泛型而不是固定形状：响应体有设置视图、历史数组、状态表各不相同的形状，\n * 而序列化只关心它能被 JSON 表达。\n */\nexport function sendJson<T>(\n  res: ServerResponse,\n  status: number,\n  body: T,\n  headers: Record<string, string> = {},\n): void {\n  res.writeHead(status, {\n    \"content-type\": \"application/json; charset=utf-8\",\n    \"cache-control\": \"no-store\",\n    ...headers,\n  });\n  res.end(JSON.stringify(body));\n}\n\n/**\n * 失败负载。三个字段分开不是冗余：客户端把 `error` 当提示文本、把 `code` 当分流依据（版本冲突靠\n * `SETTINGS_CONFLICT` 判，不靠中文文案），`details` 给结构化细节——合成一个字符串就等于让客户端\n * 去匹配文案，而文案是本地化的。\n */\ninterface FailureBody {\n  /** 面向用户的失败原因。 */\n  error?: string;\n  /** 结构化细节（请求体非法等）。 */\n  details?: string;\n  /** 补充说明（如合法取值范围）；客户端不读它，用它的是直接看响应的排查者。 */\n  hint?: string;\n  /** 机器可判的失败类别。 */\n  code?: string;\n}\n\n/** 写一个失败响应：`{ ok: false, error: {...} }`，与端点的成功体同族。 */\nexport function sendFailure(\n  res: ServerResponse,\n  status: number,\n  failure: FailureBody,\n  headers: Record<string, string> = {},\n): void {\n  sendJson(res, status, { ok: false, error: failure }, headers);\n}\n\n/** 围栏拒绝体：`error` 是**裸字符串**，与端点失败体的对象形状不同，这是刻意的——旧客户端读失败提示的顺序是\n * 「`details` → `error` → `HTTP <status>`」，而它识别局域网直连只认最后那条兜底里的状态码。把 403 包成对象，\n * 提示文案就会变成「非回环请求」、状态码消失，「请改用 https 访问」的引导随之失效。\n *\n * `code` / `status` 是与 `error` 并列的**新增 sibling 字段**（#769）：新客户端按结构化字段分流，\n * 不再依赖「服务端必须永远保持 `error` 为裸字符串」这条隐式契约；旧客户端读不到它们，行为不变。\n * 因此三者共存，而不是把 `error` 升级成对象——后者会让新旧客户端都退到兜底路径上去。\n * `allow` 不进 body：它已是 405 的标准头（同一份事实两处声明，就有两处先腐烂）。 */\nexport function sendRefused(\n  res: ServerResponse,\n  status: number,\n  code: RefusalCode,\n  reason: string,\n  headers: Record<string, string> = {},\n): void {\n  sendJson(res, status, { error: reason, code, status }, headers);\n}\n\n/** 认证围栏 401/403 的结构化拒绝出口；调用方不再各自携带 refusal code 映射。 */\nexport function sendRouteRefusal(res: ServerResponse, rejection: 401 | 403): void {\n  sendRefused(\n    res,\n    rejection,\n    rejection === 401 ? REFUSAL_CODES.UNAUTHORIZED : REFUSAL_CODES.FORBIDDEN_LOOPBACK,\n    rejection === 401 ? \"unauthorized\" : \"forbidden: loopback-only\",\n  );\n}\n\n/**\n * 注册端点组，返回摘除器清单（与装配顺序相反地释放）。\n *\n * **中途抛错整单回滚**：本函数逐条注册，第 N 条抛错时前 N-1 条已经挂在宿主上，而它们的摘除器\n * 只存在于下面这个局部表里——调用方（按返回值登记）拿不到它们，不就地摘就是永久泄漏\n * （实测后续卸载摘掉 0 条路由）。\n *\n * 回滚与成功路径共用同一把「逐项隔离」的尺子：一条摘除器抛错不阻断其余。实测组合故障（注册第 4 条\n * kinds 抛错，且第 3 条 status 的摘除器也抛错）下去掉隔离，则 3 条里只摘 1 条、泄漏 2 条，抛给调用方的\n * 错误还会从「注册失败」变成「摘除失败」——那同时违反本文件「清理路径不盖首因」那条承诺。\n *\n * **「逆序」这一半在这里不钉**：8 条路由彼此独立、谁先撤没有语义差别，把整条序钉死只会让加一条\n * 端点就红一次。真正有语义的那处逆序在 api 域装配面（「帧订阅排在第一条路由之前」，先断帧的来路\n * 再拆它的出口），那一处有判据。\n */\nexport function registerEndpoints(\n  register: RegisterRoute,\n  endpoints: Endpoint[],\n  logger: LoggerPort,\n  remote: RemoteAccessPort,\n): Array<() => void> {\n  const disposers: Array<() => void> = [];\n  try {\n    registerAll(register, endpoints, logger, disposers, remote);\n  } catch (error) {\n    // 整单回滚：已挂的逐个摘除、不留「已注册」的假记忆。清理路径不盖首因，也不上报。\n    for (const dispose of disposers.splice(0).reverse()) {\n      try {\n        dispose();\n      } catch {\n        // 一个资源的清理失败不拖垮其余：跳过其余等于把它们都留在宿主上。\n      }\n    }\n    throw error;\n  }\n  return disposers;\n}\n\n/** 逐条注册并把每条的摘除器记进 `disposers`（单独一层是为了让回滚罩住整个注册过程）。 */\nfunction registerAll(\n  register: RegisterRoute,\n  endpoints: Endpoint[],\n  logger: LoggerPort,\n  disposers: Array<() => void>,\n  remote: RemoteAccessPort,\n): void {\n  for (const endpoint of endpoints) {\n    disposers.push(\n      register({\n        kind: \"exact\",\n        path: endpoint.path,\n        handler: (req, res) => {\n          const rejection = remote.fence(req);\n          if (rejection !== undefined) {\n            sendRouteRefusal(res, rejection);\n            return;\n          }\n          const handle = endpoint.methods[(req.method ?? \"\") as HttpMethod];\n          if (handle === undefined) {\n            // `allow` 是 405 该带的头，调用方不必回翻文档；状态码与文案仍与旧协议一致，\n            // 新增的只是与之并列的机读 code/status。\n            sendRefused(\n              res,\n              405,\n              REFUSAL_CODES.METHOD_NOT_ALLOWED,\n              `method not allowed: ${req.method}`,\n              {\n                allow: Object.keys(endpoint.methods).join(\", \"),\n              },\n            );\n            return;\n          }\n          try {\n            const done = handle(req, res);\n            // 异步端点失败落在 promise、同步端点落在 catch：收口只有一处，但两条路都要接上，\n            // 否则异步端点的异常会变成未捕获拒绝。\n            if (done instanceof Promise) {\n              done.catch((cause) => {\n                reportFailure(res, logger, cause instanceof Error ? cause.message : String(cause));\n              });\n            }\n          } catch (cause) {\n            reportFailure(res, logger, cause instanceof Error ? cause.message : String(cause));\n          }\n        },\n      }),\n    );\n  }\n}\n\n/**\n * 异常收口：记日志并回 500。响应头可能已经发出（SSE 端点尤其如此），所以只在不曾写过时才补 500\n * ——重复写会抛 `ERR_HTTP_HEADERS_SENT`，把一次端点失败升级成宿主侧的未捕获异常。\n */\nfunction reportFailure(res: ServerResponse, logger: LoggerPort, reason: string): void {\n  logger.warn(`dsh-notifier: 浏览器端点处理失败 — ${reason}`);\n  if (!res.headersSent) sendFailure(res, 500, { error: reason });\n}\n"
    },
