      "path": "packages/dsh-notifier/src/server/api/impl/stream/index.ts",
      "content": "/** api 域流块：SSE 连接、序号与断线补拉（共享层枢纽只管连接表、心跳与主动回收）。**序号**持久化在 `seq.json` 且重启后\n * 接着数——重置会让重连客户端把旧帧当新的，表现为「偶尔少一条通知」；**补拉**走 `?since=N`（EventSource 自动重连不带 query）。 */\nimport type { IncomingMessage, ServerResponse } from \"node:http\";\nimport {\n  createSseHub,\n  type SseEvictStats,\n  type SseHub,\n} from \"../../../../../../../shared/sse-hub.js\";\nimport {\n  readTextFileSync,\n  writeTextAtomic,\n  SEQ_FILE_NAME,\n  notifierFile,\n} from \"../../../shared/interface.ts\";\nimport type { OutgoingFrame, RemoteAccessPort } from \"../../deps.ts\";\nimport type { StreamBuildPort, StreamDeps, StreamEvent } from \"./type.ts\";\n\n/** 补拉缓冲上限（条）：断线重连能回放的窗口，超出后只能从最新开始接。 */\nconst REPLAY_LIMIT = 200;\n\n/** 心跳间隔（毫秒）：与客户端 60s 看门狗对齐，留足两次失败的余地。 */\nconst HEARTBEAT_MS = 30000;\n\n/** 开流锚点。注释帧客户端不解析，它的作用是**立即 flush 响应头**：Node 会缓冲响应头直到第一次写入，没有这一行，\n * 客户端要等到第一个心跳（30s 后）才从 CONNECTING 进入 OPEN。 */\nconst CONNECTED = \": connected\\n\\n\";\n\n/** 线协议里的通知事件（`ping` 之外的那一支）。 */\ntype NotifyEvent = Extract<StreamEvent, { type: \"notify\" }>;\n\n/** 未装配时的占位。占位值不会被真正读到（`installed` 守卫），它的作用是让字段有确定的类型、不必每个使用点判空。 */\nconst UNINSTALLED: StreamDeps = {\n  logger: { warn: () => {} },\n};\n\n/** 未装配的枢纽：连接表为空，`dispose` 幂等。返回形状必须与真实枢纽逐键一致，否则「未装配」与\n * 「已装配但一条都没淘汰」在 `/health` 上长得不一样。 */\nconst UNINSTALLED_HUB: SseHub = {\n  register: () => {},\n  unregister: () => {},\n  broadcast: () => {},\n  size: () => 0,\n  evictStats: () => ({\n    close: 0,\n    error: 0,\n    stalled: 0,\n    maxage: 0,\n    destroyed: 0,\n    dispose: 0,\n  }),\n  connHealth: () => [],\n  dispose: () => {},\n};\n\n/** 生产默认建面：真读盘、真建表（端口不是为测试开的后门，生产恒走这一份）。 */\nconst REAL_BUILD: StreamBuildPort = {\n  open(file) {\n    return { seq: readSeq(file), hub: createSseHub({ heartbeatMs: HEARTBEAT_MS }) };\n  },\n};\n\n/** 流枢纽：连接表在共享层，序号与补拉在本块。 */\nclass StreamHub {\n  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */\n  private installed = false;\n  /** 装配入参（失败出口）。 */\n  private deps: StreamDeps = UNINSTALLED;\n  /** 枢纽：心跳与回收由共享层跑。 */\n  private hub: SseHub = UNINSTALLED_HUB;\n  /** 单调序号：上次进程留下的值往后接着数。 */\n  private seq = 0;\n  /** 补拉缓冲：只留最近 `REPLAY_LIMIT` 条。 */\n  private replay: StreamEvent[] = [];\n  /** 序号落盘位置：DSH home 由环境决定、进程内不变，故随实例一次性定下。 */\n  private readonly file = notifierFile(SEQ_FILE_NAME);\n  /** 建面端口：进程事实的边界，默认就是真实建面（换端口走 `installStreamBuild`）。 */\n  private build: StreamBuildPort = REAL_BUILD;\n\n  /**\n   * 装配：读回上次的序号，建起连接表与心跳。**建面抛错即整单失败**，本块自己不留半装配——\n   * 唯一的复位面是 `release()`，由调用方在回滚里调。\n   */\n  install(deps: StreamDeps): void {\n    if (this.installed) throw new Error(\"dsh-notifier: api 流只能装配一次\");\n    // 闸先翻再建面：建面失败时本块的 `installed` 已经是真，唯一能把它放回去的是调用方回滚时\n    // 走的那次 `release()`（故这行不能挪到建面之后——那样「失败即未装配」就成立，\n    // 调用方那次 release 反而多余，而本块自己无从知道该不该收面）。\n    this.installed = true;\n    this.deps = deps;\n    const opened = this.build.open(this.file);\n    this.seq = opened.seq;\n    this.hub = opened.hub;\n  }\n\n  /** 换掉建面端口（只给测试注入失败面用；生产不调——默认值就是真实建面）。 */\n  useBuild(port: StreamBuildPort): void {\n    this.build = port;\n  }\n\n  /** 卸载：停心跳、关连接、忘掉缓冲。序号留在盘上，下次接着数。 */\n  release(): void {\n    this.hub.dispose();\n    this.hub = UNINSTALLED_HUB;\n    this.replay = [];\n    this.installed = false;\n  }\n\n  /** 当前连接数。语义是**服务端未释放的句柄数**，不是「在线设备数」：两者混起来会让刷新页面的残留句柄看起来像多了\n   * 一台设备。 */\n  size(): number {\n    return this.hub.size();\n  }\n\n  /** 回收原因计数：`/health` 的 `sseEvicts` 观测面（常量大小的聚合）。per-conn 明细（`connHealth`）\n   * 故意不上去——它随连接数增长，而 `/health` 经 lan-proxy 对局域网可见。 */\n  evictStats(): SseEvictStats {\n    return this.hub.evictStats();\n  }\n\n  /** GET /events：接上一条 SSE 连接，并回放 `?since` 之后的帧。 */\n  handle(\n    req: IncomingMessage,\n    res: ServerResponse,\n    remote: RemoteAccessPort,\n  ): 401 | 403 | undefined {\n    if (!this.installed) {\n      res.writeHead(503);\n      res.end();\n      return undefined;\n    }\n    const admission = remote.admitStream(req);\n    if (\"rejection\" in admission) return admission.rejection;\n\n    let closed = false;\n    let peerEnded = false;\n    let disposePeer: (() => void) | undefined;\n    const closeStream = (): void => {\n      if (closed) return;\n      closed = true;\n      this.hub.unregister(res);\n    };\n    res.on(\"close\", () => {\n      closeStream();\n      const dispose = disposePeer;\n      disposePeer = undefined;\n      if (!peerEnded) dispose?.();\n    });\n    if (admission.peer !== undefined) {\n      try {\n        disposePeer = remote.bindPeer(\n          admission.peer,\n          () => {\n            peerEnded = true;\n            closeStream();\n          },\n          \"dsh-notifier: raw SSE bound to admitted Peer\",\n        );\n      } catch {\n        return 403;\n      }\n    }\n    res.writeHead(200, {\n      \"content-type\": \"text/event-stream; charset=utf-8\",\n      \"cache-control\": \"no-store\",\n      connection: \"keep-alive\",\n      // 反代缓冲会把 SSE 攒成一次性大响应，客户端看起来像「连上了但一直没消息」。\n      \"x-accel-buffering\": \"no\",\n    });\n    res.write(CONNECTED);\n    for (const event of this.since(sinceOf(req))) res.write(encode(event));\n    this.hub.register(res);\n    return undefined;\n  }\n\n  /**\n   * 广播一条通知帧：翻成线协议 → 编号 → 入缓冲 → 落序号 → 推给所有连接。翻译（`body`→`message`、\n   * `pop`→`playOnly`）在这里而不在裁决管线：线协议是**浏览器出口**的约定，管线对外给的是内部帧，\n   * 翻译上移会让内部词汇被线协议反向锁死。\n   */\n  publish(payload: OutgoingFrame): void {\n    if (!this.installed) return;\n    this.seq += 1;\n    const { frame } = payload;\n    const event: NotifyEvent = {\n      type: \"notify\",\n      seq: this.seq,\n      kind: payload.kind,\n      title: frame.title,\n      message: frame.body,\n      ts: Date.now(),\n      sound: frame.sound,\n      // 可见性判定归浏览器出口，帧自描述：客户端拿到就能执行，不必回查自己那份可能已过期的配置快照。\n      whenVisible: frame.whenVisible,\n    };\n    // 缺席而不是 `false`：客户端判的是 `=== true`，而缺席让不认识这个字段的旧客户端收到的帧\n    // 与从前逐字节一致。\n    if (!frame.pop) event.playOnly = true;\n    this.replay.push(event);\n    if (this.replay.length > REPLAY_LIMIT) this.replay.splice(0, this.replay.length - REPLAY_LIMIT);\n    // 序号是 fire-and-forget：写失败只让下次重启回退几条，不值得挡住广播。\n    void writeTextAtomic(this.file, `${this.seq}\\n`);\n    this.hub.broadcast(encode(event));\n  }\n\n  /** 序号大于 `since` 的帧，按序。 */\n  private since(value: number): StreamEvent[] {\n    return this.replay.filter((event) => event.type === \"notify\" && event.seq > value);\n  }\n}\n\n/** 一帧的 SSE 文本：`data:` 行加空行结束（客户端按 `onmessage` 收）。 */\nfunction encode(event: StreamEvent): string {\n  return `data: ${JSON.stringify(event)}\\n\\n`;\n}\n\n/** 从请求 URL 取 `?since=`；缺失或非法一律当 0（= 回放整个缓冲）。 */\nfunction sinceOf(req: IncomingMessage): number {\n  const query = (req.url ?? \"\").split(\"?\")[1];\n  if (query === undefined) return 0;\n  const raw = new URLSearchParams(query).get(\"since\");\n  if (raw === null) return 0;\n  const parsed = Number.parseInt(raw, 10);\n  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;\n}\n\n/** 读回上次进程留下的序号；文件缺失或内容不是正数都从 0 起算。 */\nfunction readSeq(file: string): number {\n  const read = readTextFileSync(file);\n  if (!read.ok) return 0;\n  const parsed = Number.parseInt(read.text.trim(), 10);\n  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;\n}\n\n/** 本域唯一的流实例：类不外放，外面 `new` 不出第二份序号。 */\nexport const streamHub = new StreamHub();\n\n/**\n * 装载建面端口（只给测试用；生产不调用——默认值就是真实建面）。\n *\n * 与 `channels/impl/system/deps.ts` 的 `installSystemDeps` 同款：真实实现是缺省值，\n * 端口槽只是把「建面会抛错」这个今天不可达的事实变成可注入的。\n */\nexport function installStreamBuild(port: StreamBuildPort): void {\n  streamHub.useBuild(port);\n}\n\n/** 复位建面端口，与 `installStreamBuild` 配对；重复调用无害。 */\nexport function releaseStreamBuild(): void {\n  streamHub.useBuild(REAL_BUILD);\n}\n"
    },
    {
      "path": "shared/host-utils.ts",
      "content": "// dsh 插件家族共享层 — 宿主端辅助函数（单一事实源）。\n//\n// 历史：writeJson 5 份、errorMessage 4 份、readBody 4 份 3 档 limit 在各插件\n// 逐字复制并已漂移。统一由本模块提供；readBody 的 limit 由调用方显式传入，\n// 消除隐式差异。\n\nimport { Buffer } from \"node:buffer\";\nimport type { IncomingMessage, ServerResponse } from \"node:http\";\n\n/**\n * Loopback 围栏判定参数。\n * - allowCrossSiteNoCors（#549）：仅 serve 类资源伺服路由使用——放行「显式\n *   sec-fetch-mode: no-cors」的跨站子资源请求（sandbox iframe opaque origin\n *   的相对路径 css/js/img 加载）；cors fetch/XHR 与 navigate 仍拒绝。\n *   普通 /api 路由必须保持默认（不传 options）拒绝一切 cross-site。\n */\nexport interface LoopbackOptions {\n  allowCrossSiteNoCors?: boolean;\n  /**\n   * 非回环请求的官方认证源。必须每次请求现取 `ctx.connection`，不得缓存 service 实例。\n   * 未提供、读取失败或 connection 已卸载时由 routeFenceRejection fail-closed。\n   */\n  remoteAdmission?: RemoteAdmissionSource;\n  /** 长连接请求的官方 peer admission；仅 SSE/流式 route 使用。 */\n  remotePeerAdmission?: RemotePeerAdmissionSource;\n}\n\n/** 官方 `ctx.connection.requestRejection()` 的最小结果面。 */\nexport type RemoteAdmissionRejection = 401 | 403 | undefined;\n\n/** 一次非回环请求的官方 admission；`undefined` 表示 Host/Origin 与凭据均已通过。 */\nexport type RemoteAdmission = (request: IncomingMessage) => RemoteAdmissionRejection;\n\n/** admission 的动态来源；每次 HTTP 请求调用一次，使 connection 替换或卸载立即生效。 */\nexport type RemoteAdmissionSource = () => RemoteAdmission | undefined;\n\n/**\n * 官方 `PeerScope` 中本层绑定长连接所需的最小公开面。rc.1 的 PeerScope.ctx 是随 Peer\n * dispose 的 Cordis Context；这里只保留 `effect`，不持有认证材料，也不复制认证算法。\n */\nexport interface RemotePeerScope {\n  readonly ctx: {\n    effect(execute: () => () => void, label?: string): unknown;\n  };\n}\n\n/** 官方 `connection.admit()` 的成功/拒绝结果。 */\nexport type RemotePeerAdmissionResult =\n  { readonly peer: RemotePeerScope } | { readonly rejection: 401 | 403 };\n\n/** 一次非回环长连接请求的官方 admission。 */\nexport type RemotePeerAdmission = (request: IncomingMessage) => RemotePeerAdmissionResult;\n\n/** peer admission 的动态来源；同样必须在每次连接请求时重新读取 connection。 */\nexport type RemotePeerAdmissionSource = () => RemotePeerAdmission | undefined;\n\n/** cordis Context 的最小读取面；`strict: false` 是面向可选服务探测的官方调用形态。 */\nexport interface ConnectionLookupContext {\n  get(name: string, strict?: boolean): unknown;\n}\n\n/**\n * Loopback 围栏：请求必须来自回环地址 + 回环 Host，且满足跨站/来源约束，\n * 否则拒绝。默认拒绝一切 `sec-fetch-site: cross-site` 请求（DNS 重绑定 +\n * 跨站防御）；仅当 `options.allowCrossSiteNoCors` 为 true 时，**显式带\n * `sec-fetch-mode: no-cors` 的跨站子资源请求**放行（见 issue #549：\n * sandbox iframe 的 opaque origin 会使其相对路径子资源请求（css/js/img）\n * 一律呈 cross-site，serve 虚拟伺服需放行 no-cors 标签型加载，但 cors\n * fetch/XHR 与 navigate 仍拒绝）。\n *\n * 跨站放行是安全语义变更点，**只允许 serve 类资源伺服路由使用**；\n * 普通 /api 路由必须保持默认拒绝。\n *\n * @param request - Node http 请求对象。\n * @param options - 可选判定参数。\n * @returns 是否允许。\n */\n/**\n * 对端地址是否回环（IPv4 / IPv6 / IPv4-mapped 三种写法）。fail-closed：拿不到地址即拒绝。\n *\n * 单立一函数是因为它与 Host 头是**两个不同的事实**：前者在传输层（谁连过来的），\n * 后者在应用层（他说自己是谁）。合成一条 if 时，「改 Host 白名单」会连带改到对端判定。\n */\nfunction isLoopbackPeerAddress(request: IncomingMessage): boolean {\n  const address = request.socket?.remoteAddress;\n  return address === \"127.0.0.1\" || address === \"::1\" || address === \"::ffff:127.0.0.1\";\n}\n\n/**\n * Host 头解析与判定：必须是 127.0.0.1 / localhost / [::1]，否则拒绝。\n * 返回解析好的 URL（同源比较要用它的 host），解析失败或不在白名单即 undefined。\n */\nfunction loopbackHostUrlOf(request: IncomingMessage): URL | undefined {\n  const host = request.headers.host;\n  if (typeof host !== \"string\") return undefined;\n  let hostUrl: URL;\n  try {\n    hostUrl = new URL(`http://${host}`);\n  } catch {\n    return undefined;\n  }\n  if (\n    hostUrl.hostname !== \"127.0.0.1\" &&\n    hostUrl.hostname !== \"localhost\" &&\n    hostUrl.hostname !== \"[::1]\"\n  ) {\n    return undefined;\n  }\n  return hostUrl;\n}\n\n/**\n * 跨站判定（#549）：默认拒绝一切 cross-site；仅 serve 资源路由经 allowCrossSiteNoCors\n * 放行「显式 no-cors」的跨站子资源（标签型加载）。\n * fail-closed：cross-site 请求缺少 no-cors 标记（含头缺失的防御语义）一律拒绝，不猜测放行。\n * 同源（无 sec-fetch-site 或非 cross-site）恒放行——同源与否由 Origin 头那一段再判一次。\n */\nfunction crossSiteRequestAllowed(request: IncomingMessage, options: LoopbackOptions): boolean {\n  if (request.headers[\"sec-fetch-site\"] !== \"cross-site\") return true;\n  return options.allowCrossSiteNoCors === true && request.headers[\"sec-fetch-mode\"] === \"no-cors\";\n}\n\nexport function isLoopbackRequest(\n  request: IncomingMessage,\n  options: LoopbackOptions = {},\n): boolean {\n  if (!isLoopbackPeerAddress(request)) return false;\n  const hostUrl = loopbackHostUrlOf(request);\n  if (hostUrl === undefined) return false;\n  if (!crossSiteRequestAllowed(request, options)) return false;\n  const origin = request.headers.origin;\n  if (origin === undefined) return true;\n  try {\n    return new URL(origin).host === hostUrl.host;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * 从当前 Context 建立动态 admission 源。\n *\n * 闭包只保留 Context；每次请求重新 `get(\"connection\", false)`，不缓存 connection 或方法。\n */\nexport function liveConnectionAdmission(ctx: ConnectionLookupContext): RemoteAdmissionSource {\n  return () => {\n    const connection = ctx.get(\"connection\", false);\n    if (\n      connection === null ||\n      typeof connection !== \"object\" ||\n      !(\"requestRejection\" in connection) ||\n      typeof connection.requestRejection !== \"function\"\n    ) {\n      return undefined;\n    }\n    const requestRejection = connection.requestRejection;\n    return (request) => requestRejection.call(connection, request) as RemoteAdmissionRejection;\n  };\n}\n\nfunction isRemotePeerScope(value: unknown): value is RemotePeerScope {\n  return (\n    value !== null &&\n    typeof value === \"object\" &&\n    \"ctx\" in value &&\n    value.ctx !== null &&\n    typeof value.ctx === \"object\" &&\n    \"effect\" in value.ctx &&\n    typeof value.ctx.effect === \"function\"\n  );\n}\n\n/** 现读可选动态源；source 缺失或读取抛错都由调用方统一 fail-closed。 */\nfunction currentRemoteSource<T>(source?: () => T | undefined): T | undefined {\n  try {\n    return source?.();\n  } catch {\n    return undefined;\n  }\n}\n\n/** 官方短请求 admission 结果只接受 undefined / 401 / 403，其余一律收敛为 403。 */\nfunction normalizeRemoteRejection(value: unknown): RemoteAdmissionRejection {\n  if (value === undefined) return undefined;\n  return value === 401 || value === 403 ? value : 403;\n}\n\n/** 官方长连接 admission 结果只接受有效 PeerScope 或 401/403，其余一律 fail-closed。 */\nfunction normalizePeerAdmissionResult(value: unknown): RemotePeerAdmissionResult {\n  if (value !== null && typeof value === \"object\") {\n    if (\"peer\" in value && isRemotePeerScope(value.peer)) return { peer: value.peer };\n    if (\"rejection\" in value && (value.rejection === 401 || value.rejection === 403)) {\n      return { rejection: value.rejection };\n    }\n  }\n  return { rejection: 403 };\n}\n\n/** 从当前 Context 建立长连接 peer admission 源，成功结果保留官方 PeerScope。 */\nexport function liveConnectionPeerAdmission(\n  ctx: ConnectionLookupContext,\n): RemotePeerAdmissionSource {\n  return () => {\n    const connection = ctx.get(\"connection\", false);\n    if (\n      connection === null ||\n      typeof connection !== \"object\" ||\n      !(\"admit\" in connection) ||\n      typeof connection.admit !== \"function\"\n    ) {\n      return undefined;\n    }\n    const admit = connection.admit;\n    return (request) => normalizePeerAdmissionResult(admit.call(connection, request) as unknown);\n  };\n}\n\n/**\n * 长连接请求认证：loopback 仍走旧快路径且不绑定 connection Peer；非回环必须从\n * 当前官方 connection admission 拿到 PeerScope，供调用方注册 peer.ctx.effect()。\n */\nexport function admitLongLivedRequest(\n  request: IncomingMessage,\n  options: LoopbackOptions = {},\n): { readonly peer?: RemotePeerScope } | { readonly rejection: 401 | 403 } {\n  if (isLoopbackPeerAddress(request)) {\n    return isLoopbackRequest(request, options) ? {} : { rejection: 403 };\n  }\n\n  const admission = currentRemoteSource(options.remotePeerAdmission);\n  if (typeof admission !== \"function\") return { rejection: 403 };\n\n  try {\n    return normalizePeerAdmissionResult(admission(request));\n  } catch {\n    return { rejection: 403 };\n  }\n}\n\n/**\n * 把长连接清理登记到官方 PeerScope 的 ctx.effect；Peer 释放/connection 卸载时自动执行。\n * 返回的 disposer 供客户端先断开时注销 effect，重复调用由 Cordis 保持幂等。\n */\nexport function bindPeerLifecycle(\n  peer: RemotePeerScope,\n  cleanup: () => void,\n  label: string,\n): () => void {\n  const dispose = peer.ctx.effect(() => () => cleanup(), label);\n  let disposed = false;\n  return () => {\n    if (disposed) return;\n    disposed = true;\n    if (typeof dispose === \"function\") void dispose();\n  };\n}\n\n/**\n * 路由认证裁决：回环快路径保持原样，非回环交给官方 connection admission。\n *\n * 非回环路径中，source/service/method 缺失、抛错或返回未知值一律 403。`undefined`\n * 只来自当前官方 admission，表示 Host/Origin 与浏览器/API 凭据均已通过。\n */\nexport function routeFenceRejection(\n  request: IncomingMessage,\n  options: LoopbackOptions = {},\n): RemoteAdmissionRejection {\n  if (isLoopbackPeerAddress(request)) {\n    return isLoopbackRequest(request, options) ? undefined : 403;\n  }\n\n  const admission = currentRemoteSource(options.remoteAdmission);\n  if (typeof admission !== \"function\") return 403;\n\n  try {\n    return normalizeRemoteRejection(admission(request));\n  } catch {\n    return 403;\n  }\n}\n\n/**\n * 路由认证 + 方法白名单低阶守卫。\n *\n * **对本守卫的执行顺序**：回环快路径；非回环走官方 connection admission，\n * 401/403 原样返回；认证通过后才检查方法，方法不在白名单 → 405。该顺序仅对\n * **套本守卫的端点**成立——个别端点（如\n * mcp-manager /config）是端点级方法分流先于 loopback 的刻意例外，不适用。\n *\n * @param req - Node http 请求对象。\n * @param res - 响应对象。\n * @param methods - 允许的 HTTP 方法白名单。\n * @param loopbackOptions - 透传给\n *   isLoopbackRequest 的可选判定参数；`remoteAdmission` 只在非回环路径启用。\n * @returns 是否放行（true 时调用方继续处理请求）。\n */\nexport function guardLoopbackMethod(\n  req: IncomingMessage,\n  res: ServerResponse,\n  methods: string[],\n  loopbackOptions?: LoopbackOptions,\n): boolean {\n  const rejection = routeFenceRejection(req, loopbackOptions);\n  if (rejection !== undefined) {\n    writeJson(res, rejection, {\n      error: rejection === 401 ? \"unauthorized\" : \"forbidden: loopback-only\",\n    });\n    return false;\n  }\n  // `req.method` 在 @types/node 上是 `string | undefined`。断言不改变运行时取值：\n  // 缺 method 时 includes 仍为 false，照原样落 405，不存在被误放行的分支。\n  if (!methods.includes(req.method as string)) {\n    writeJson(res, 405, { error: `method not allowed: ${req.method}` });\n    return false;\n  }\n  return true;\n}\n\n/**\n * 写 JSON 响应（统一带 referrer-policy 头，防 referrer 泄露）。\n * @param res - 响应对象。\n * @param status - HTTP 状态码。\n * @param payload - 序列化为 JSON 的负载。\n */\nexport function writeJson(res: ServerResponse, status: number, payload: unknown): void {\n  res.writeHead(status, {\n    \"content-type\": \"application/json; charset=utf-8\",\n    \"referrer-policy\": \"no-referrer\",\n  });\n  res.end(JSON.stringify(payload));\n}\n\n/**\n * 序列化一帧 SSE data 行（输出形如 `data: <json>\\n\\n`）。\n * 与 mcp-manager / notifier / provider-usage 三处历史实现逐字同构（#472 收敛）。\n * JSON.stringify(undefined) 返回 undefined，拼接为 `data: undefined\\n\\n`；含真实\n * 换行的 payload 由 JSON 转义为字面 `\\n`，不拆多行 data 帧。现状三处均无调用点\n * 传 undefined（payload 恒为对象字面量），该行为仅为对齐历史、不额外兜底，\n * 非承诺契约——若未来收紧（抛错/省略）不视为破坏兼容（需单开决策）。\n * @param payload - 序列化为 JSON 的 SSE 帧负载。\n * @returns SSE data 帧文本。\n */\nexport function sseData(payload: unknown): string {\n  return `data: ${JSON.stringify(payload)}\\n\\n`;\n}\n\n/** 请求体读不出来的具体成因：供端点在失败文案里说清是哪一种。 */\nexport type JsonBodyInvalidReason = \"too-large\" | \"unreadable\" | \"malformed\" | \"not-object\";\n\n/** `readJsonBodyOutcome` 的成因可辨结果：缺席（可选 body 未给）/ 合法对象 / 非法（带具体成因）。 */\nexport type JsonBodyOutcome =\n  | { kind: \"absent\" }\n  | { kind: \"json\"; value: object }\n  | { kind: \"invalid\"; reason: JsonBodyInvalidReason };\n\n/**\n * 读请求 body（JSON）并**保留失败成因**。\n *\n * 为什么需要它：`readJsonBody` 把「没给 body」「JSON 畸形」「超出上限」「JSON 合法但不是对象」\n * 收敛成同一个 undefined，调用方想区分「可选 body 缺席」与「给了但读不出来」只能靠猜。对**有副作用**\n * 的端点，这个歧义是有代价的：畸形请求会走到「按缺省处理」那条路，等于拿垃圾输入触发真实动作。\n * 需要 fail-closed 的端点用本函数；宽松端点继续用 `readJsonBody`（它是本函数的薄包装）。\n * @param req - Node http 请求对象（或 async-iterator 桩）。\n * @param limit - 字节上限（默认 2MB）。\n * @returns 成因可辨的结果。\n */\nexport async function readJsonBodyOutcome(\n  req: IncomingMessage,\n  limit = 2 * 1024 * 1024,\n): Promise<JsonBodyOutcome> {\n  const chunks: Buffer[] = [];\n  let size = 0;\n  try {\n    for await (const chunk of req) {\n      size += chunk.length;\n      if (size > limit) return { kind: \"invalid\", reason: \"too-large\" };\n      chunks.push(chunk);\n    }\n  } catch {\n    return { kind: \"invalid\", reason: \"unreadable\" };\n  }\n  let text: string;\n  try {\n    text = Buffer.concat(chunks).toString(\"utf8\");\n  } catch {\n    // 块不是 Buffer（流被 setEncoding 成字符串之类）：与「读不出来」同义。这里必须在 try 内——\n    // 本函数对外的承诺是**不抛错**（宽版面 `readJsonBody` 是它的薄包装），抛出去会打到调用方。\n    return { kind: \"invalid\", reason: \"unreadable\" };\n  }\n  // 空 body（含纯空白）与「没写 body」是同一件事：可选参数缺席，不是错误。\n  if (text.trim() === \"\") return { kind: \"absent\" };\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(text);\n  } catch {\n    return { kind: \"invalid\", reason: \"malformed\" };\n  }\n  if (typeof parsed !== \"object\" || parsed === null)\n    return { kind: \"invalid\", reason: \"not-object\" };\n  return { kind: \"json\", value: parsed };\n}\n\n/**\n * 宽松读请求 body（JSON）：解析失败或超限返回 undefined（不抛错），由调用方决定响应。\n * 成因不可辨——要区分「缺席」与「非法」用 `readJsonBodyOutcome`。与 readBody 共用限长语义。\n * @param req - Node http 请求对象（或 async-iterator 桩）。\n * @param limit - 字节上限（默认 2MB）。\n * @returns 解析后的 JSON 对象；空/非法/超限返回 undefined。\n */\nexport async function readJsonBody(\n  req: IncomingMessage,\n  limit = 2 * 1024 * 1024,\n): Promise<object | undefined> {\n  const outcome = await readJsonBodyOutcome(req, limit);\n  return outcome.kind === \"json\" ? outcome.value : undefined;\n}\n\n/**\n * 把任意抛出的值转成可读错误消息。\n * @param error - 任意抛出的值。\n * @returns 可读错误消息。\n */\nexport function errorMessage(error: unknown): string {\n  try {\n    if (error instanceof Error) return error.message;\n    return String(error);\n  } catch {\n    return \"[unrenderable thrown value]\";\n  }\n}\n\n/**\n * 读请求 body（JSON，限长防滥用）。\n * 兼容两种请求形态：Node 事件流（data/end）与 async-iterator 桩（测试用）。\n * @param req - Node http 请求对象（或 async-iterator 桩）。\n * @param limit - 字节上限（显式传入，默认 256KB）。\n * @returns 解析后的 JSON 对象（空 body 返回 {}）。\n */\nexport function readBody(req: IncomingMessage, limit = 256 * 1024): Promise<object> {\n  // async-iterator 形态（部分测试桩）：逐块读取，限长检查。\n  if (typeof req[Symbol.asyncIterator] === \"function\" && typeof req.on !== \"function\") {\n    return (async () => {\n      const chunks: Buffer[] = [];\n      let size = 0;\n      for await (const chunk of req) {\n        size += chunk.length;\n        if (size > limit) throw new Error(\"body too large\");\n        chunks.push(chunk);\n      }\n      return chunks.length === 0 ? {} : JSON.parse(Buffer.concat(chunks).toString(\"utf8\"));\n    })();\n  }\n  // Node 事件流形态。\n  return new Promise((resolvePromise, reject) => {\n    const chunks: Buffer[] = [];\n    let size = 0;\n    req.on(\"data\", (chunk: Buffer) => {\n      size += chunk.length;\n      if (size > limit) {\n        reject(new Error(\"body too large\"));\n        req.destroy();\n        return;\n      }\n      chunks.push(chunk);\n    });\n    req.on(\"end\", () => {\n      try {\n        resolvePromise(\n          chunks.length === 0 ? {} : JSON.parse(Buffer.concat(chunks).toString(\"utf8\")),\n        );\n      } catch (error) {\n        const e = error as Error;\n        reject(new Error(`invalid JSON body: ${e.message}`));\n      }\n    });\n    req.on(\"error\", reject);\n  });\n}\n"
    },
    {
      "path": "packages/dsh-notifier/src/client/index.tsx",
      "content": "/**\n * dsh-notifier — 浏览器端（自包含）。\n *\n * 行为：\n * - 在「设置」面板注册独立 tab「通知中心」（settings.section 插槽：参照\n *   provider-usage「用量统计」tab；不做 plugin.item 双插槽重复展示——入口只有这一个）；\n * - 通知半区保留并与 DOM 解耦：SSE /events 订阅 + 60s 看门狗 +\n *   visibilitychange 重建 + 多标签租约 + 音频手势解锁，不依赖任何插件 DOM；\n * - 历史记录最近 10 条收进卡片；卡片动作区含清理记录（两段式确认）/\n *   请求权限/发送测试通知；三端降级文案迁入卡片；\n * - 配置读取走 GET /config 包装体 {ok,user,revision,effective,writable}，保存走\n *   PUT {patch, expectedRevision}（基线 diff 只提变更键，防组合层默认值回写覆盖）。\n */\n// 浏览器半区干净模块：只导出 apply/inject；React 由构建期 external 注入（经 factory\n// 注入的 require(\"react\") 解析，dsh web 不暴露全局 React）。契约外壳（IIFE/load/\n// Symbol.toStringTag 装配）由 scripts/build/build-client.ts 统一生成——源码不写任何 loader。\n// 样式：独立 style.css（见同目录），build-client 的 .css text-loader 构建期内联为字符串\nimport STYLE from \"./style.css\";\n// R3：跨包原语层的表现面（唯一副本 shared/client/ui/ui.css）经 ts 侧拼接注入。\n// .css 走同一个 text-loader，仍是纯文本内联，产物依旧自包含单文件、零运行时依赖。\n// **顺序是 UI_CSS + STYLE（原语层在前）**：原语层当底座、各包 style.css 在其之上，\n// 这样包内的窄屏/领域覆盖（同优先级下靠后者胜）永远压得住原语默认值——\n// provider-usage 的 @media 480px 段就靠这条把 .dsu-badge/.dsu-surface-pane 改窄屏尺寸。\nimport UI_CSS from \"../../../../shared/client/ui/ui.css\";\n// 样式注入收敛 shared/client/ensure-style.js：本包只补\n// { id, cssText, version } 实参；STYLE_ID/CSS_VERSION 常量保留为调用实参来源，\n// disposer（getElementById(STYLE_ID)）沿用常量。\nimport { ensureStyle } from \"../../../../shared/client/ensure-style.js\";\n// 通知帧的展示策略（纯判定）、多标签租约、音频出口：外部事实（时钟 / storage /\n// AudioContext）都从端口进来，于是「未解锁 / 被挂起 / 被拒绝」与租约三分支都能在 node 里\n// 跑出判据。音色单点仍在 src/shared/interface.ts，改由 notify/audio.ts 消费。\nimport { bindTranslate, t, type Translate } from \"./locale.ts\";\nimport { createAudioEngine, type AudioContextLike } from \"./notify/audio.ts\";\nimport { closeNotificationsOf, trackNotification } from \"./notify/registry.ts\";\nimport { titleFlasher } from \"./notify/title.ts\";\nimport { claimMaster as claimMasterLease, MASTER_KEY } from \"./notify/lease.ts\";\nimport { startNotifySession, type EventSourceLike, type NotifySession } from \"./notify/session.ts\";\nimport {\n  displayChannelOf,\n  fallbackChannelOf,\n  frameAccepted,\n  soundPolicyOf,\n} from \"./notify/policy.ts\";\nimport * as React from \"react\";\n// i18n：复用官方 dsh-client-locale——zh/en 双语字典，LocaleNamespaceMap\n// 声明合并进官方 ui-slots 类型面；仅 import type（编译期擦除，无运行时依赖）。\nimport { zh, en, type NotifierLocaleKey } from \"./locales.ts\";\n// 能力自检面的投影（宿主面归一化 + 浏览器面判定）收在同一处：判定与文案必须同源，\n// 两处各写一遍就等于把「未知不该被渲染成可用」这条口径分叉。\nimport { clientDiagnosticsOf } from \"./capabilities.ts\";\nimport type { ClientFacts } from \"./capabilities.ts\";\n// 页面内即时反馈（横幅 / 短提示）：非安全上下文下唯一的降级提醒通道。\nimport { showBanner, toast } from \"./notify/display.ts\";\n// 设置草稿的纯逻辑与保存串行 guard：零 React 零 DOM，可被 node 直接 import——它们决定\n// 「保存什么」，因此必须是可判据的面（原先挂在公开 apply 上，实测零消费者）。\nimport {\n  assignChannelFields,\n  diffSettingsPayload,\n  domainPayload,\n  rebaseSettings,\n  snapshotBaseline,\n} from \"./settings/diff.ts\";\nimport { createSaveGuard } from \"./settings/save-guard.ts\";\n// 测试投递的终态收敛轮询（#912 症状2）：纯逻辑模块，单测直测，卡片内只做薄接线。\nimport { pollChannelStatus } from \"./settings/status-poll.ts\";\n// 一次失败请求的结构化结论（是否围栏拒答 / 引导文案 / 展示正文）与结构化字段挂载：\n// 判定顺序是两端契约（结构化优先、状态码与文案兜底），故收在纯函数模块里由单测直接打红。\nimport { apiFailureOf, markHttpFailure } from \"./api-error.ts\";\nimport type { HttpFailure } from \"./api-error.ts\";\nimport { dryRunReasonText } from \"./reason-text.ts\";\n// 设置卡的渲染原子层：普通函数返回 JSX，依赖（t / statusMap / patch / sendTest / 平台 / 诊断\n// 视图）一律显式传参——原子层不读卡片状态，搬家不会让闭包静默捕获到旧 state。\nimport { channelsPane } from \"./settings/panes/channels.tsx\";\nimport { eventsPane } from \"./settings/panes/events.tsx\";\nimport { historyPane } from \"./settings/panes/history.tsx\";\nimport { tabIcon } from \"./settings/parts/kind-icons.tsx\";\nimport { dirtyStatusText, routeSummaryText } from \"./settings/parts/route-text.ts\";\nimport type { ChannelStatusMap } from \"./settings/parts/status.tsx\";\nimport type {\n  ClearHistoryResult,\n  ConflictLatest,\n  ConfigSnapshot,\n  HistoryRecordView,\n  MetaView,\n  PostKindResult,\n  PutResult,\n  RegisteredKindView,\n  SendTestResult,\n  SettingsChannelView,\n  SettingsPatch,\n  SettingsView,\n} from \"./settings/types.ts\";\n// 两端共享面 src/shared/interface.ts：音色白名单、通知类型表、频道 id 归一化、webhook 预设\n// （模板 / 认证白名单）与理由 code 的事实源都在这里，客户端只消费，不再各写一份副本——跨端\n// 漂移的症状是「设置页选得到、宿主拒收」与「勾了频道却收不到」。该目录的模块必须零 import\n// （或同目录相对），判据见 scripts/test/shared-leaf-imports.test.ts。\nimport {\n  KIND_SEVERITY,\n  channelIdOf,\n  createDisposerStack,\n  isBuiltinKind,\n} from \"../shared/interface.ts\";\nimport type { DisposerStack } from \"../shared/disposers.ts\";\nimport type { NotifySeverity } from \"../shared/interface.ts\";\n// 显式类型导入，先把 @deepseek-ai/dsh-client-ui-slots 拉进模块解析图：上游发布物\n// lib/types/*.d.ts 相对导入保留 .ts 后缀，declare module 增强的模块名解析会判\n// TS2664（microsoft/TypeScript#63960 同类；上游修复发布物后此行可删）。\nimport type { LocaleNamespaceMap as _LocaleNamespaceMap } from \"@deepseek-ai/dsh-client-ui-slots\";\n// 宿主服务面取官方类型本体（仅 import type）：locale = LocaleRuntime、slots = SlotRegistry，\n// 装配处的窄读面用 Pick<> 派生，不在本文件手抄签名。\nimport type { LocaleRuntime } from \"@deepseek-ai/dsh-client-locale/client\";\nimport type { SlotRegistry } from \"@deepseek-ai/dsh-client-ui-renderer/client\";\n\ndeclare module \"@deepseek-ai/dsh-client-ui-slots\" {\n  interface LocaleNamespaceMap {\n    /** dsh-notifier 设置卡/历史列表/权限降级说明文案。 */\n    notifier: NotifierLocaleKey;\n  }\n}\n\n/** 本插件字典命名空间（宿主 locale 服务注册用）。 */\nconst NS = \"notifier\";\n\nconst ROUTES = {\n  config: \"/api/dsh-notifier/config\",\n  events: \"/api/dsh-notifier/events\",\n  health: \"/api/dsh-notifier/health\",\n  diagnostics: \"/api/dsh-notifier/diagnostics\",\n  test: \"/api/dsh-notifier/test\",\n  history: \"/api/dsh-notifier/history\",\n  status: \"/api/dsh-notifier/status\",\n  kinds: \"/api/dsh-notifier/kinds\",\n};\n\nconst STYLE_ID = \"dsh-notifier-style\";\n// 每次样式契约变更后 bump（版本号单调递增，保证 ensureStyle 判定为新版本并重注入）\n// 声音行/三态/试听样式加入时再次 bump。\n// 能力自检行（dn-ch-diag）加入时再次 bump。\n// dry-run 结果行与脏态测试按钮样式加入时再次 bump。\nconst CSS_VERSION = \"ui-v3-2\";\n// 浏览器通知图标（内联 SVG data URL，零外部资源；铃铛造型）。\nconst NOTIFY_ICON =\n  \"data:image/svg+xml;utf8,\" +\n  encodeURIComponent(\n    '<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><rect width=\"24\" height=\"24\" rx=\"5\" fill=\"#0f9d6e\"/><path fill=\"#fff\" d=\"M12 4a1 1 0 0 1 1 1v.55A5.5 5.5 0 0 1 17.5 11v2.3l1.45 1.45a1 1 0 0 1-.7 1.7H5.75a1 1 0 0 1-.7-1.7L6.5 13.3V11A5.5 5.5 0 0 1 11 5.55V5a1 1 0 0 1 1-1zm-2.5 13a2.5 2.5 0 0 0 5 0h-5z\"/></svg>',\n  );\n\n/**\n * kind → 展示强度（severity）css 修饰符（事件行/历史行色点）。事实源在 src/shared/kinds.ts\n * （两端共享面），与宿主端定稿读同一张表。\n *\n * 未知 kind（外部注册）回落 info：收口前是 `KIND_SEV[kind] || \"info\"`，而那张表的键集\n * 恰好等于内置 kind 全集，故「是内置 kind 就查表、否则 info」与它是同一条判据。\n */\nfunction severityOf(kind: string): NotifySeverity {\n  return isBuiltinKind(kind) ? KIND_SEVERITY[kind] : \"info\";\n}\n\n/**\n * 请求浏览器通知权限（必须在用户手势内调用，Chrome 才接受）。\n * 完成后回调（无论结果），用于刷新卡片权限状态。\n */\nfunction requestPermission(onDone?: () => void) {\n  if (!(\"Notification\" in window)) return;\n  try {\n    Notification.requestPermission()\n      .then(function () {\n        if (onDone) onDone();\n      })\n      .catch(function () {\n        if (onDone) onDone();\n      });\n  } catch {\n    if (onDone) onDone();\n  }\n}\n\n// ------------------------------------------------------------ 通知显示（半区）\n\n/** 本页已弹出的系统通知（保留最近 5 条，超出即关最旧的）。 */\n/** 本标签页的租约身份：跨 apply 复用——重新挂载仍是同一个标签，不该被当成「另一个标签」\n *  而在 15 秒内静默（见 notify/lease.ts 的模块头）。 */\nconst TAB_ID = Math.random().toString(36).slice(2);\n\n/**\n * 跨实例共享的音频出口：AudioContext 与播放节流窗口必须全页一份，否则重复挂载会让同一帧\n * 响两次或该响的不响。用 const 单例承载闭包状态，而不是模块级 let。\n */\nconst audioEngine = createAudioEngine({ ctor: audioContextCtorOf, now: () => Date.now() });\n\n/** 本页的主标签租约（storage 与时钟走端口，判定在 notify/lease.ts）。 */\nfunction claimMaster(): boolean {\n  return claimMasterLease(TAB_ID, {\n    now: () => Date.now(),\n    read: () => localStorage.getItem(MASTER_KEY),\n    write: (value) => {\n      localStorage.setItem(MASTER_KEY, value);\n    },\n  });\n}\n\n/** 页面是否处于安全上下文（HTTPS 或 localhost）——系统级 Notification 的前提。 */\nfunction isSecureContext() {\n  return window.isSecureContext === true;\n}\n\n/** 系统级浏览器通知是否可用（安全上下文 + 已授权）。 */\nfunction systemNotificationUsable() {\n  if (!(\"Notification\" in window)) return false;\n  if (!isSecureContext()) return false;\n  return Notification.permission === \"granted\";\n}\n\n/** 平台 AudioContext 构造器：前缀化的老 Safari 名字不在标准 DOM 类型里，取用点收在这里，\n *  能力自检与解锁共用同一判据。 */\nfunction audioContextCtorOf(): (new () => AudioContextLike) | undefined {\n  const legacy = (window as unknown as { webkitAudioContext?: unknown }).webkitAudioContext;\n  return (window.AudioContext ?? legacy) as (new () => AudioContextLike) | undefined;\n}\n\n/**\n * 本页的能力事实。判定与文案都在 capabilities.ts（纯函数、不碰 DOM）：\n * 这里只负责把浏览器里的现状读出来，读法本身没有可断言的分支。\n */\nfunction clientFacts(): ClientFacts {\n  const hasApi = \"Notification\" in window;\n  return {\n    notificationApi: hasApi,\n    secureContext: isSecureContext(),\n    // 权限值只作数据带过去（值域外的取值由判定侧按「无法判定」处理）\n    permission: hasApi ? String(Notification.permission) : \"unknown\",\n    audio: audioEngine.facts(),\n  };\n}\n\n/**\n * 通知展示总入口。\n *\n * 判定（走哪条通道、什么声音策略）在 notify/policy.ts 的纯函数里；这里只做三件事：过主标签\n * 租约、执行判定给出的通道、按策略自播。顺序是刻意的——租约在构造 Notification 之前，副标签\n * 连横幅都不弹；Notification 构造抛错则降级到页面内提醒（同一条降级判定重算一次）。\n *\n * @param opts.sound 服务端帧级声音策略；缺省（0.2.3 的帧没有这个字段）按「跟随系统默认」。\n * @param opts.playOnly 只响不弹：不弹实体、仅按需自播。\n * @param owner 页面级单例（已弹通知 / 标题闪烁 / <style>）的归属令牌：热更或重复 apply 时，\n *   后装实例的清理不许动先前实例登记的资源。\n */\nfunction showNotification(\n  kind: string,\n  title: string,\n  message: string,\n  opts: { sound?: unknown; playOnly?: boolean },\n  owner: object,\n) {\n  const playOnly = opts.playOnly === true;\n  const policy = soundPolicyOf(opts.sound, playOnly);\n  // 多标签去重：弹实体与只响不弹自播一律先过主标签租约，副标签静默\n  if (!claimMaster()) return;\n  const notificationUsable = systemNotificationUsable();\n  if (\n    displayChannelOf({\n      playOnly,\n      notificationUsable,\n      visibility: document.visibilityState,\n    }) === \"notification\"\n  ) {\n    try {\n      const notification = new Notification(title, {\n        body: message,\n        tag:\n          \"dsh-notifier-\" + kind + \"-\" + Date.now() + \"-\" + Math.random().toString(36).slice(2, 8),\n        icon: NOTIFY_ICON,\n        silent: policy.silent,\n      });\n      notification.onclick = () => {\n        // 本行的判据是已登记的缺口而不是遗漏：happy-dom 的 BrowserWindow.focus() 是 TODO\n        // 空实现（不派发事件、无任何可观测副作用），而本仓测试纪律禁用 vi.spyOn，故「点击\n        // 通知会把窗口拉到前台」在当前夹具下写不出可打红的判据。变可测的条件是把这里抽成\n        // 接收 window 端口的纯函数，由假件记录调用。\n        window.focus();\n        notification.close();\n      };\n      trackNotification(notification, owner);\n      // selfplay 模式：Notification 已 silent 防双响，页内补播\n      if (policy.selfPlay && audioEngine.gate()) audioEngine.playTone(policy.tone);\n      return;\n    } catch (error) {\n      console.warn(\"[dsh-notifier] 浏览器通知失败，降级为页面内提醒：\", error);\n    }\n  }\n  // 降级通道 / 只响不弹：横幅或标题闪烁；声音按帧策略\n  const fallback = fallbackChannelOf(playOnly, document.visibilityState);\n  if (fallback === \"banner\") showBanner(kind, title, message);\n  else if (fallback === \"title\") titleFlasher.flash(title, owner);\n  if (policy.selfPlay && audioEngine.gate()) audioEngine.playTone(policy.tone);\n}\n\nfunction handleNotifyFrame(payload: Record<string, unknown>, owner: object) {\n  // 帧字段按展示契约收窄：SSE 载荷恒为服务端序列化的通知帧；缺失回落空串（标签拼装恒有\n  // 定义，不把 \"undefined\" 拼进 tag）。判定字段（whenVisible/playOnly/sound）保持 unknown\n  // 原样交判定侧（frameAccepted/soundPolicyOf 本就按 unknown 解释）。\n  const kind = typeof payload.kind === \"string\" ? payload.kind : \"\";\n  const title = typeof payload.title === \"string\" ? payload.title : \"\";\n  const message = typeof payload.message === \"string\" ? payload.message : \"\";\n  // 测试通知无条件提醒；其余帧在页面可见时不打扰，除非帧自带 whenVisible——判定见 notify/policy.ts\n  if (\n    !frameAccepted({\n      kind: kind,\n      whenVisible: payload.whenVisible,\n      playOnly: payload.playOnly,\n      visibility: document.visibilityState,\n    })\n  ) {\n    return;\n  }\n  showNotification(\n    kind,\n    title,\n    message,\n    {\n      sound: payload.sound,\n      playOnly: payload.playOnly === true,\n    },\n    owner,\n  );\n}\n\n// ------------------------------------------------------------ SSE 半区\n\n/**\n * 当前会话句柄。用一个 const 容器而不是模块级 let：容器本身不变，变的是它指向的会话——\n * 也让「谁该把它清空」这件事有身份可比（disposer 只在仍指向自己的会话时才清）。\n */\nconst eventsHandle: { current: NotifySession | null } = { current: null };\n\n// ------------------------------------------------------------ 设置卡片\n\n/**\n * 非 2xx 一律抛错，并把结构化字段挂到 Error 上（判定侧读它，见 api-error.ts）。\n *\n * 读路径此前完全不看 `r.ok`：403 的围栏体（`{error, code, status}`）被当数据用——历史读成空数组、\n * 诊断面把拒答体当自检载荷。`body` 传的是已解析的响应体，围栏体的 code/status 才挂得上。\n * 抛错不是给用户看的（各调用点的 catch 决定降级），是为了让「非 2xx」不再伪装成一份空数据。\n */\nfunction assertOk(r: Response, body: unknown): void {\n  if (!r.ok) throw markHttpFailure(new Error(\"HTTP \" + r.status), r.status, body);\n}\n\n/** 加载 GET /config 包装体 → 结构化 {user, revision, effective, writable}。 */\nfunction fetchConfig(): Promise<ConfigSnapshot> {\n  return fetch(ROUTES.config, { headers: { accept: \"application/json\" } }).then(function (\n    r: Response,\n  ) {\n    return r.json().then(function (body: ConfigSnapshot) {\n      if (!r.ok) {\n        const nested = body.error;\n        const detail =\n          typeof nested === \"object\" && nested !== null\n            ? nested.details || nested.error\n            : undefined;\n        throw markHttpFailure(new Error(detail || \"HTTP \" + r.status), r.status, body);\n      }\n      return body;\n    });\n  });\n}\n\n/** 拉取最近历史记录（最近 10 条，倒序）。 */\nfunction fetchHistory(): Promise<HistoryRecordView[]> {\n  return fetch(ROUTES.history, { headers: { accept: \"application/json\" } }).then(function (\n    r: Response,\n  ) {\n    return r.json().then(function (body: { records?: unknown }) {\n      assertOk(r, body);\n      const records: unknown = body.records;\n      return (Array.isArray(records) ? records : []).slice(-10).reverse() as HistoryRecordView[];\n    });\n  });\n}\n\n/** 拉取频道投递状态（per-channel 最近投递终态）。\n *  失败向上抛（调用方决定保留旧态而非清空状态行）。 */\nfunction fetchStatus(): Promise<ChannelStatusMap> {\n  return fetch(ROUTES.status, { headers: { accept: \"application/json\" } }).then(function (\n    r: Response,\n  ) {\n    return r.json().then(function (body: { channels?: unknown }) {\n      assertOk(r, body);\n      const channels: unknown = body.channels;\n      return (\n        typeof channels === \"object\" && channels !== null ? channels : {}\n      ) as ChannelStatusMap;\n    });\n  });\n}\n\n/**\n * 拉取动态 kind 清单（注册表 + 确认态）。\n *\n * 失败一律回落空清单（调用点的既有降级：清单区显示「暂无」），故这里自己吞掉 `assertOk` 抛出的\n * 错误——判据仍在（非 2xx 的 body 不再被当清单读），只是不给用户报错。\n */\nfunction fetchKinds(): Promise<RegisteredKindView[]> {\n  return fetch(ROUTES.kinds, { headers: { accept: \"application/json\" } })\n    .then(function (r: Response) {\n      return r.json().then(function (body: { kinds?: unknown }) {\n        assertOk(r, body);\n        const kinds: unknown = body.kinds;\n        return (Array.isArray(kinds) ? kinds : []) as RegisteredKindView[];\n      });\n    })\n    .catch(function () {\n      return [];\n    });\n}\n\n/**\n * 拉取宿主能力自检（GET /diagnostics）。15s 超时兜底：服务端首次探测要起子进程，可能慢；\n * 超时与失败一律静默降级成「读不到」，由调用方把那块整体不渲染——诊断面缺席不该让设置页报错。\n */\n/** 宿主平台（/health platform）：服务端运行机器的 OS——系统通道弹在宿主机器上，浏览器 OS\n *  与宿主 OS 可异机，所以不能拿 navigator.platform 猜。失败/未知一律 null，由渲染侧回落通用文案。 */\nfunction fetchHealth(): Promise<string | null> {\n  return fetch(ROUTES.health, { headers: { accept: \"application/json\" } })\n    .then(function (r: Response) {\n      return r.json().then(function (body: { platform?: unknown }) {\n        assertOk(r, body);\n        return typeof body.platform === \"string\" ? body.platform : null;\n      });\n    })\n    .catch(function () {\n      return null;\n    });\n}\n\nfunction fetchDiagnostics(): Promise<unknown> {\n  const ctrl: AbortController | null =\n    typeof AbortController !== \"undefined\" ? new AbortController() : null;\n  const timer: ReturnType<typeof setTimeout> | null = ctrl\n    ? setTimeout(function () {\n        ctrl!.abort();\n      }, 15000)\n    : null;\n  const init: RequestInit = { headers: { accept: \"application/json\" } };\n  if (ctrl) init.signal = ctrl.signal;\n  return fetch(ROUTES.diagnostics, init)\n    .then(function (r) {\n      return r.json().then(function (body: unknown) {\n        assertOk(r, body);\n        return body;\n      });\n    })\n    .finally(function () {\n      if (timer !== null) clearTimeout(timer);\n    });\n}\n\n/** 动态 kind 确认（POST /kinds {kind, confirmed}）。 */\nfunction postKind(kind: string, confirmed: boolean): Promise<PostKindResult> {\n  return fetch(ROUTES.kinds, {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\" },\n    body: JSON.stringify({ kind: kind, confirmed: confirmed }),\n  }).then(function (r: Response) {\n    return r.json().then(function (body: PostKindResult) {\n      if (!r.ok) {\n        const nested = body.error;\n        const detail =\n          typeof nested === \"object\" && nested !== null\n            ? nested.details || nested.error\n            : undefined;\n        throw markHttpFailure(new Error(detail || \"HTTP \" + r.status), r.status, body);\n      }\n      return body;\n    });\n  });\n}\n\n/**\n * 测试通知（channelId 可选——per-channel 测试，收敛到 service 管线）。\n *\n * draftChannels 给出即 dry-run（#912 症状1）：body 带 {channelId, draft: {channels}}，\n * 测眼前草稿、同步返回实测结论，全程不写 history / status。服务端总预算 15s，客户端错峰\n * 18s 中断（B7：让服务端的 408 先到；中断只丢弃本次结果，在飞的投递无法撤回，见面板声明）。\n * 无 draft 时走老路（已保存配置），语义一个字不改。\n */\nfunction sendTestReq(channelId?: string, draftChannels?: unknown): Promise<SendTestResult> {\n  const isDryRun = draftChannels !== undefined;\n  const ctrl: AbortController | null =\n    isDryRun && typeof AbortController !== \"undefined\" ? new AbortController() : null;\n  const timer: ReturnType<typeof setTimeout> | null = ctrl\n    ? setTimeout(function () {\n        ctrl!.abort();\n      }, 18000)\n    : null;\n  const body =\n    channelId === undefined\n      ? {}\n      : isDryRun\n        ? { channelId: channelId, draft: { channels: draftChannels } }\n        : { channelId: channelId };\n  let chain = fetch(ROUTES.test, {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\" },\n    body: JSON.stringify(body),\n    signal: ctrl ? ctrl.signal : undefined,\n  }).then(function (r: Response) {\n    return r.json().then(function (body: SendTestResult) {\n      if (!r.ok) {\n        const nested = body.error;\n        const detail =\n          typeof nested === \"object\" && nested !== null\n            ? nested.details || nested.error\n            : undefined;\n        // 围栏拒绝体的 error 是裸字符串；403 的 https 引导改由结构化 code/status 判定，\n        // 文案里的状态码只作旧宿主的兜底（见 api-error.ts），故两者都挂上。\n        throw markHttpFailure(new Error(detail || \"HTTP \" + r.status), r.status, body);\n      }\n      return body;\n    });\n  });\n  if (timer !== null) {\n    const pending = timer;\n    chain = chain.finally(function () {\n      clearTimeout(pending);\n    });\n  }\n  return chain;\n}\n\n// ── SettingsCard 的四个呈现块（#732 E6）────────────────────────────────────\n// 它们与组件本体是两类不同的变化来源：组件持有 state 与事件回调，这四块只做「给定这些值，\n// 渲染成什么」。混写在组件里时，改一条降级文案要去数半个组件的闭包依赖。\n\n/**\n * 三端降级文案（服务不可用 / 非安全上下文 / 平台不支持）。\n * 浏览器通知权限状态行已移入「浏览器通知」频道卡，故这里只留三条全局说明。\n */\nfunction degradationNotes(\n  meta: MetaView | null,\n  t: Translate,\n  isSecureContext: () => boolean,\n): React.ReactNode[] {\n  const degradation: React.ReactNode[] = [];\n  if (meta && meta.writable === false) {\n    degradation.push(\n      <div className=\"dn-set-note\" key=\"settings-unavailable\">\n        {t(\"settingsSvcDown\")}\n      </div>,\n    );\n  }\n  if (\"Notification\" in window) {\n    if (!isSecureContext()) {\n      degradation.push(\n        <div className=\"dn-set-note\" key=\"insecure\">\n          {t(\"httpDegraded\")}\n        </div>,\n      );\n    }\n  } else {\n    degradation.push(\n      <div className=\"dn-set-note\" key=\"noapi\">\n        {t(\"iosUnsupported\")}\n      </div>,\n    );\n  }\n  return degradation;\n}\n\n/** 三个 tab 的按钮：分段 icon + 待确认 kind 徽标（确认流是安全设计，不可被 tab 埋没）。 */\nfunction tabBar(\n  activeTab: \"events\" | \"channels\" | \"history\",\n  pendingKinds: number,\n  t: Translate,\n  setActiveTab: (v: \"events\" | \"channels\" | \"history\") => void,\n): React.ReactNode {\n  const tab = (which: \"events\" | \"channels\" | \"history\", label: string, badge: React.ReactNode) => (\n    <button\n      type=\"button\"\n      className={\"dn-set-tab\" + (activeTab === which ? \" dn-set-tabActive\" : \"\")}\n      onClick={function () {\n        setActiveTab(which);\n      }}\n    >\n      {tabIcon(which)}\n      {label}\n      {badge}\n    </button>\n  );\n  return (\n    <div className=\"dn-set-tabs\">\n      {tab(\n        \"events\",\n        t(\"secEvents\"),\n        pendingKinds > 0 ? <span className=\"dn-set-tabBadge\">{String(pendingKinds)}</span> : null,\n      )}\n      {tab(\"channels\", t(\"secChannels\"), null)}\n      {tab(\"history\", t(\"secHistory\"), null)}\n    </div>\n  );\n}\n\n/**\n * dry-run 的 status 词 → 状态标签文案（认不出的词原样透出，不替它编一个）。\n *\n * `request-failed` 排在已知值里（#1016 残留 4）：它是**客户端请求层**造的状态（400/408/429/中断），\n * 不经服务端的 reason 闭集，但照样渲染在这一行上——不在表里就 `return status` 把英文原样透出去，\n * 于是状态标签与理由两处英文。标签复用 `chStatusSkipped`（「未发出」/ \"Not sent\"）而不是另开 key：\n * 这个状态的事实是**请求压根没发出去**，投递面根本没被触达。标成「投递失败」是一句**事实性错误\n * 断言**——没有任何东西被投递过，于是界面上会出现「投递失败：测试请求失败：HTTP 400」，把用户沿着\n * 「Bark 端点拒了 / 凭据错了」这条方向去排查，而真正的原因在请求层；同一格里的 `skipped`\n * （被免打扰等挡在投递面之前）本就在用它，一格两义不必新开 pair。请求层与投递层的区别由紧邻的\n * 理由行讲清（`testRequestFail` 前缀 + 原文）。为零新增 key 的差别新开一对 locale，\n * 只会让表多一行而信息量不变。\n */\nfunction dryRunStatusTextOf(status: string, t: Translate): string {\n  if (status === \"ok\") return t(\"chStatusOk\");\n  if (status === \"failed\") return t(\"chStatusFailed\");\n  if (status === \"skipped\") return t(\"chStatusSkipped\");\n  if (status === \"request-failed\") return t(\"chStatusSkipped\");\n  return status;\n}\n\n/**\n * dry-run 结果行：独立行、打标「草稿测试·未落盘」，常驻 [去保存][放弃草稿]，通过不自动保存。\n * 在飞（pending）时只显结论位、不给动作按钮——两个动作在结论出来前无处可去。\n */\nfunction dryRunRowOf(\n  dryRun: { channelId: string; pending: boolean; status?: string; reason?: string } | null,\n  saving: boolean,\n  t: Translate,\n  saveFor: () => void,\n  discard: () => void,\n): React.ReactNode {\n  if (dryRun === null) return null;\n  const result = dryRun.pending ? null : (\n    <span className=\"dn-dryrunResult\">\n      {dryRun.channelId +\n        \" · \" +\n        dryRunStatusTextOf(dryRun.status || \"\", t) +\n        (dryRun.reason ? \"：\" + dryRun.reason : \"\")}\n    </span>\n  );\n  const actions = dryRun.pending ? null : (\n    <span className=\"dn-dryrunActions\">\n      <button\n        type=\"button\"\n        className=\"dn-set-btn dn-set-btnSmall dn-set-save\"\n        disabled={saving}\n        onClick={saveFor}\n      >\n        {t(\"dryRunGoSave\")}\n      </button>\n      <button\n        type=\"button\"\n        className=\"dn-set-btn dn-set-btnSmall\"\n        disabled={saving}\n        onClick={discard}\n      >\n        {t(\"dryRunDiscard\")}\n      </button>\n    </span>\n  );\n  return (\n    <div className=\"dn-dryrun\" role=\"status\" title={t(\"chTestDraftTitle\")}>\n      <span className=\"dn-dryrunTag\">{t(\"dryRunTag\")}</span>\n      {result === null ? <span className=\"dn-dryrunPending\">{t(\"dryRunPending\")}</span> : result}\n      {actions}\n      <div className=\"dn-dryrunNote\">{t(\"dryRunNote\")}</div>\n    </div>\n  );\n}\n\n/** 当前 tab 的 pane：三个 pane 是**条件调用**（普通函数返回 JSX，非 active tab 根本不调用\n *  ——保持既有条件渲染语义；改成组件会引入挂载/卸载）。故按 tab 名分发到对应调用。 */\nfunction activePaneOf(\n  activeTab: \"events\" | \"channels\" | \"history\",\n  panes: {\n    events: () => React.ReactNode;\n    channels: () => React.ReactNode;\n    history: () => React.ReactNode;\n  },\n): React.ReactNode {\n  if (activeTab === \"events\") return panes.events();\n  if (activeTab === \"channels\") return panes.channels();\n  return panes.history();\n}\n\n/** 409 冲突双动作横幅（非模态：横幅期间可继续编辑；动作触发时实时重算本地变更）。 */\nfunction conflictBanner(\n  conflict: { entry: string; latest: ConflictLatest } | null,\n  saving: boolean,\n  t: Translate,\n  loadLatest: () => void,\n  overwrite: () => void,\n  ignore: () => void,\n): React.ReactNode {\n  if (conflict === null) return null;\n  return (\n    <div className=\"dn-conflict\" role=\"alert\">\n      <span className=\"dn-conflictText\">\n        {t(conflict.entry === \"channels\" ? \"conflictChannels\" : \"conflictTitle\")}\n      </span>\n      <span className=\"dn-conflictActions\">\n        <button type=\"button\" className=\"dn-set-btn dn-set-btnSmall\" onClick={loadLatest}>\n          {t(\"conflictLoadLatest\")}\n        </button>\n        <button\n          type=\"button\"\n          className=\"dn-set-btn dn-set-btnSmall dn-set-save\"\n          disabled={saving}\n          onClick={overwrite}\n        >\n          {t(\"conflictOverwrite\")}\n        </button>\n        {/* 「忽略」= 关闭横幅、草稿保留原样 */}\n        <button type=\"button\" className=\"dn-set-btn dn-set-btnSmall\" onClick={ignore}>\n          {t(\"conflictIgnore\")}\n        </button>\n      </span>\n    </div>\n  );\n}\n\n/** 底部保存栏的左侧状态位：保存反馈优先于脏文案，两者都没有就留空。 */\nfunction saveStatusNode(\n  saved: { msg: string; err: boolean } | null,\n  dirtyText: string | null,\n): React.ReactNode {\n  if (saved !== null) {\n    return <span className={saved.err ? \"dn-set-error\" : \"dn-set-saved\"}>{saved.msg}</span>;\n  }\n  return dirtyText === null ? null : <span className=\"dn-dirty\">{dirtyText}</span>;\n}\n\n/**\n * 设置面板独立 tab「通知中心」（settings.section 插槽渲染的 React 卡片）。\n * 重设计：频道卡分区（browser/system/bark×n，状态灯 + per-channel\n * 测试）+ 事件路由复选组（kindRoutes 单源双向编辑）+ 动态 kind 确认清单 +\n * 高级参数折叠；字段全量 + 基线 diff 只提变更键 + 历史最近 10 条 + 动作区 +\n * 三端降级文案。保存走 PUT {patch, expectedRevision}（乐观并发，冲突提示刷新）。\n */\nfunction SettingsCard() {\n  const ReactHooks = React;\n  const useState = ReactHooks.useState;\n  const useEffect = ReactHooks.useEffect;\n  // 设置草稿：形状是服务端 settings 对象，客户端只读其中几个键（真正的形状声明在宿主侧）。\n  // 声明成 Record 而不是让 useState(null) 推成 null：否则每次读键都要靠调用方把值当 any 传进来。\n  const draft = useState(null as SettingsView | null);\n  const settings = draft[0];\n  const setSettings = draft[1];\n  // 声明形状而不是让 useState(null) 推成 null：读侧只取 writable，但写成 never 的话\n  // 任何一次读取都要靠调用方把值当 any 传进来才编得过（就是本行原先的形态）。\n  const meta = useState(null as MetaView | null);\n  const metaValue = meta[0];\n  const setMeta = meta[1];\n  // 保存反馈（i18n 重构：msg + err 结构化状态，不能用文案内容判断错误态）\n  const savedDraft = useState(null as { msg: string; err: boolean } | null);\n  const saved = savedDraft[0];\n  const setSaved = function (msg: string, err?: boolean) {\n    savedDraft[1](msg ? { msg: msg, err: err === true } : null);\n  };\n  const historyDraft = useState(null as HistoryRecordView[] | null);\n  const history = historyDraft[0];\n  const setHistory = historyDraft[1];\n  const clearArmed = useState(false);\n  const clearArmedValue = clearArmed[0];\n  const setClearArmed = clearArmed[1];\n  // 频道投递状态（/status channels map，键=bark:<id>）/ 动态 kind 清单（/kinds）\n  const statusDraft = useState({} as ChannelStatusMap);\n  const statusMap = statusDraft[0];\n  const setStatusMap = statusDraft[1];\n  // 状态表 ref 收口：sendTest 在 POST 前记下 prevTs，读 ref 而非渲染闭包（后者可能是旧帧）。\n  const statusRef = ReactHooks.useRef({} as ChannelStatusMap);\n  const kindsDraft = useState([] as RegisteredKindView[]);\n  const kindsList = kindsDraft[0];\n  const setKindsList = kindsDraft[1];\n  // 宿主能力自检载荷（/diagnostics 原样收下；归一化与文案在 capabilities.ts）。\n  // null = 还没拉到或拉取失败 → 诊断块整体不渲染（旧服务端没有这条路由也走这条路径）。\n  const diagnosticsDraft = useState(null as unknown);\n  const diagnostics = diagnosticsDraft[0];\n  const setDiagnostics = diagnosticsDraft[1];\n  // 宿主平台进 state 而不是模块变量：它是要渲染的数据。原先写成模块变量让抓取回调无法触发\n  // 重渲染——/health 晚于最后一次 setState 返回时，系统卡会一直显示通用文案直到用户再交互。\n  const hostPlatformDraft = useState(null as string | null);\n  const hostPlatform = hostPlatformDraft[0];\n  const setHostPlatform = hostPlatformDraft[1];\n  // 频道删除两段确认（实例 id）。路由编辑展开行（openRoute）随 chips\n  // 直点形态移除——chips 无展开层，routeToggle 直接落草稿。\n  const delArmedDraft = useState(null as string | null);\n  const delArmedId = delArmedDraft[0];\n  const setDelArmedId = delArmedDraft[1];\n  // levels：每个频道「待添加映射」草稿（kind + level；按频道 id 键控）\n  const levelsNewDraft = useState({} as Record<string, { kind: string; level: string }>);\n  const levelsNew = levelsNewDraft[0];\n  const setLevelsNew = levelsNewDraft[1];\n  // 卡内三 tab（通知事件 / 通知频道 / 通知记录——历史独立成 tab）。\n  // 切 tab 仅条件拼接 children——全部表单/瞬态 state 都在本组件顶层，切换零丢失。\n  const activeTabDraft = useState(\"events\" as \"events\" | \"channels\" | \"history\");\n  const activeTab = activeTabDraft[0];\n  const setActiveTab = activeTabDraft[1];\n  // 浏览器通知权限状态行在频道卡内——Notification.permission 非 React state，\n  // 请求权限完成后 bump 一次触发重渲染刷新状态行文案/隐藏按钮。\n  const permTickDraft = useState(0);\n  const permTick = permTickDraft[0];\n  const setPermTick = permTickDraft[1];\n  // webhook 凭据字段显隐态（键 = <channelId>:<field>；纯瞬态，不入配置、\n  // 不影响基线 diff——掩码值本身不回显，显隐只影响「正在输入的新值」可见性）。\n  const revealDraft = useState({} as Record<string, boolean>);\n  const revealMap = revealDraft[0];\n  const setRevealMap = revealDraft[1];\n  // 凭据字段「已被用户编辑」的键集（键 = <channelId>:<field>）。未编辑的字段保持服务端掩码\n  // 原样提交、由服务端按严格相等还原；只有用户真的输入过才把新值写进草稿——把掩码渲染成\n  // 可编辑 value 会让「在圆点后追加一个字符」变成一次真凭据覆盖（见 settings/mask.ts）。\n  const secretEditedDraft = useState({} as Record<string, boolean>);\n  const secretEdited = secretEditedDraft[0];\n  const setSecretEdited = secretEditedDraft[1];\n\n  /** 标记某凭据字段已被用户编辑（幂等）。 */\n  function markSecretEdited(key: string) {\n    if (secretEdited[key] === true) return;\n    const nextEdited: Record<string, boolean> = Object.assign({}, secretEdited);\n    nextEdited[key] = true;\n    setSecretEdited(nextEdited);\n  }\n  // 加载基线：保存时只提交与基线不同的键（增量 diff），未改动的键不提交。\n  // 用 useRef 持久化：组件每次渲染局部变量会重置为 null，导致 save() 闭包里读不到\n  // 基线而永远判定「无变化」。\n  const baselineRef = ReactHooks.useRef(null as SettingsView | null);\n  // settings / meta（revision）ref 收口——异步回调（保存成功 / trailing 补发）\n  // 一律读 ref 而非渲染闭包值，杜绝「连点第二个 PUT 带旧 revision」「补发漏提交在途\n  // 新编辑」两类陈旧闭包问题。settingsRef 由 patch（唯一写入口）在 updater 内同步。\n  const settingsRef = ReactHooks.useRef(null as SettingsView | null);\n  const metaRef = ReactHooks.useRef(null as MetaView | null);\n  // 保存串行 guard（模块级纯工厂）——同一时刻仅一个在途 PUT。\n  const saveGuardRef = ReactHooks.useRef(null as ReturnType<typeof createSaveGuard> | null);\n  if (saveGuardRef.current === null) saveGuardRef.current = createSaveGuard();\n  const saveGuard = saveGuardRef.current;\n  // 保存中 UI 态（按钮禁用 + 「保存中…」文案）\n  const savingDraft = useState(false);\n  const saving = savingDraft[0];\n  const setSaving = savingDraft[1];\n  // 409 冲突横幅态。null=无冲突；非 null={ entry, latest }——\n  // latest 为冲突时拉取的服务端最新 {effective, revision}（「加载最新/覆盖」动作\n  // 的数据源）。横幅期间用户可继续编辑（非模态），动作触发时实时重算本地变更。\n  const conflictDraft = useState(null as null | { entry: string; latest: ConflictLatest });\n  const conflict = conflictDraft[0];\n  const setConflict = conflictDraft[1];\n  // dry-run 结果（#912 症状1 B-S1-4/B8）：独立态，与 poll / loadStatus 完全隔离。\n  // - pending=true：在飞；pending=false：已有结论（status 恒为服务端回的实测结论）；\n  // - 任一草稿写入口（patch / commitSettings）即清（改草稿清结果）；\n  // - 纯内存：重载即丢；切 tab 保留（state 在卡片顶层，不随 pane 条件调用走）。\n  // - 通过不自动保存：结论只渲染，不触发任何 saveFor。\n  const dryRunDraft = useState(\n    null as null | { channelId: string; pending: boolean; status?: string; reason?: string },\n  );\n  const dryRun = dryRunDraft[0];\n  const setDryRun = dryRunDraft[1];\n\n  function loadHistory(alive: { value: boolean }) {\n    fetchHistory()\n      .then(function (records) {\n        if (alive.value) setHistory(records);\n      })\n      .catch(function () {\n        if (alive.value) setHistory([]);\n      });\n  }\n\n  function loadStatus(alive: { value: boolean }) {\n    fetchStatus()\n      .then(function (map) {\n        if (alive.value) {\n          statusRef.current = map;\n          setStatusMap(map);\n        }\n      })\n      .catch(function () {\n        // 拉取失败保留已加载状态行（不清空——旧实现 catch → {} 会把\n        // 已展示的最近投递终态抹掉，瞬时网络抖动即丢信息）\n      });\n  }\n\n  function loadKinds(alive: { value: boolean }) {\n    // 与上面的 loadStatus 同款：失败保留已加载列表，不清空（瞬时抖动不该丢已展示内容）\n    fetchKinds()\n      .then(function (list) {\n        if (alive.value) setKindsList(list);\n      })\n      .catch(function () {});\n  }\n\n  function loadHealth(alive: { value: boolean }) {\n    // 失败与未知都不提示：平台提示回落通用文案即可（用户无法处置「读不到宿主 OS」）\n    fetchHealth()\n      .then(function (platform) {\n        if (alive.value) setHostPlatform(platform);\n      })\n      .catch(function () {});\n  }\n\n  function loadDiagnostics(alive: { value: boolean }) {\n    // 失败与超时都不提示：自检面缺席时界面少一块，而不是多一条用户无法处置的错误\n    fetchDiagnostics()\n      .then(function (body) {\n        if (alive.value) setDiagnostics(body);\n      })\n      .catch(function () {});\n  }\n\n  function loadCard(alive: { value: boolean }) {\n    fetchConfig()\n      .then(function (v) {\n        if (!alive.value) return;\n        // 服务端快照收成客户端视图（HTTP 边界断言，字段形态见 settings/types.ts）。\n        // 草稿与基线双双过比较规范形（#912 症状3）：effective 含空串与 0 与空对象等价形态，\n        // 原样浅拷贝即首屏恒脏；渲染等价（见 snapshotBaseline 注释）。\n        const effective = ((v && v.effective) || {}) as SettingsView;\n        const snapshot = snapshotBaseline(\n          effective as unknown as Record<string, unknown>,\n        ) as SettingsView;\n        commitSettings(Object.assign({}, snapshot));\n        baselineRef.current = Object.assign({}, snapshot);\n        const nextMeta = {\n          user: v.user || {},\n          revision: v.revision,\n          effective: effective,\n          writable: v.writable !== false,\n        };\n        metaRef.current = nextMeta;\n        setMeta(nextMeta);\n        if (v.writable === false) setSaved(t(\"settingsUnavailable\"), true);\n      })\n      .catch(function (e: unknown) {\n        if (!alive.value) return;\n        const failure = apiFailureOf(e, t);\n        setSaved(t(\"loadFail\", { msg: failure.message, hint: failure.hint }), true);\n      });\n  }\n\n  useEffect(function () {\n    const alive = { value: true };\n    loadCard(alive);\n    loadHistory(alive);\n    loadStatus(alive);\n    loadKinds(alive);\n    loadDiagnostics(alive);\n    loadHealth(alive);\n    return function () {\n      alive.value = false;\n    };\n  }, []);\n\n  if (!settings) {\n    // 早退分支的第三态（#1016 残留 3）：`loadCard` 的 catch 已经把失败填进 `saved`（`err` 为真），\n    // 但那行状态在早退**之后**才渲染——于是局域网直连被回环围栏 403 时，`loadFail` 的提示连同\n    // `lanAccessHint` 的 HTTPS/隧道引导都到不了屏上，用户永远只看到「加载中」。\n    // 不新造文案也不新加 locale key：这条分支复用 `saved.msg`——它在 catch 里已由\n    // `t(\"loadFail\", { msg, hint })` 填好，403 时 hint 就是本地化的局域网引导。\n    // `saved.err` 正是那条已内建的分界（`setSaved` 第二参），不需要新状态。\n    return (\n      <li className=\"dn-set-card\">\n        {saved !== null && saved.err ? saved.msg : t(\"settingsLoading\")}\n      </li>\n    );\n  }\n\n  /** settings 唯一写入口（ref 收口）：updater 内同步 settingsRef——\n   *  为什么在 updater 内写（而非 useEffect latest 模式）：useEffect 是 passive\n   *  effect（paint 后异步），可能与网络宏任务回调（保存成功 / trailing 补发）\n   *  乱序；updater 内写在 state 计算的同一闭包同一时刻完成，时序零窗口。React\n   *  并发 abort 重放会重跑整个 updater 队列，最终写值恒等于最终提交的 state\n   *  （最终一致）；StrictMode 双调写同值幂等。all 调用点（loadCard /\n   *  switchControl / discardChanges / 各 patch 调用方）统一走本函数，保证\n   *  异步回调读 settingsRef.current 恒为最新草稿。\n   *  p 为对象时浅合并；为函数时以最新 prev 计算（prev => next）。 */\n  function patch(p: SettingsPatch) {\n    setSettings(function (prev) {\n      const cur: SettingsView = prev === null ? {} : prev;\n      const next = typeof p === \"function\" ? p(cur) : Object.assign({}, cur, p);\n      settingsRef.current = next;\n      return next;\n    });\n    setSaved(\"\");\n    // 任一草稿写入口变更即清 dry-run 结果（含冲突覆盖/quiet——它们走 commitSettings，见下）。\n    setDryRun(null);\n  }\n\n  /** 整体替换 settings：已知完整 next 时同步写 settingsRef 再\n   *  setState——调用方（loadCard / 冲突恢复 rebase / 静默刷新）随后可能立即\n   *  读 ref（如覆盖重提 saveFor），不能等 updater 异步执行。事件级增量编辑\n   *  仍走 patch（updater 内写 ref，天然与 state 计算同步）。 */\n  function commitSettings(next: SettingsView) {\n    settingsRef.current = next;\n    setSettings(next);\n    setSaved(\"\");\n    setDryRun(null);\n  }\n\n  /** 基线 diff：只提交与加载基线不同的键（防组合层 base 被默认值回写覆盖）。\n   *  逻辑收敛在模块级纯函数 diffSettingsPayload（供测试直测）。\n   *  读 settingsRef（非渲染闭包 settings）——trailing 补发在 .then 回调里\n   *  触发，必须取最新草稿；渲染期调用时 ref 与 state 同值，无行为差异。 */\n  function diffPayload(): Record<string, unknown> {\n    // 两个来源都可能是 null（配置还没读回来）：空草稿与 null 在 diffSettingsPayload 里同样是\n    // 「没有可提交的键」（它只遍历自有键），故显式给 {} 让类型与运行期取值一致。\n    return diffSettingsPayload(settingsRef.current || settings || {}, baselineRef.current);\n  }\n\n  /** 409 冲突恢复：拉最新 → 无脏静默刷新 / 有脏弹双动作横幅。 */\n  function handleConflict(entry: string) {\n    fetchConfig()\n      .then(function (v) {\n        if (!v) return;\n        const latest = {\n          effective: (v && v.effective) || {},\n          revision: v && v.revision,\n          user: (v && v.user) || {},\n        };\n        // 本地已无该入口脏（用户在 409 往返间撤销/放弃）→ 静默切到最新（兑现\n        // 「自动重拉重新渲染」的安全路径，不打扰）。\n        if (Object.keys(diffPayloadFor(entry)).length === 0) {\n          applyLatestQuiet(latest);\n          return;\n        }\n        setConflict({ entry: entry, latest: latest });\n        setSaved(\"\"); // 冲突横幅自带标题（conflictTitle/conflictChannels），foot 提示区清空防重复\n      })\n      .catch(function () {\n        // 拉最新失败：不弹横幅（缺最新 revision 时弹会误导），只提示可重试\n        setSaved(t(\"conflictReloadFail\"), true);\n      });\n  }\n\n  /** 无脏静默刷新：settings/baseline/meta 全部切到服务端最新（不丢任何草稿——\n   *  调用前已确认本地无脏）。 */\n  function applyLatestQuiet(latest: ConflictLatest) {\n    // 静默刷新同样收敛基线（#912 症状3）：无脏时切最新，若存原样即下一次 diff 复脏。\n    const fresh = snapshotBaseline(latest.effective || {}) as SettingsView;\n    commitSettings(fresh);\n    baselineRef.current = Object.assign({}, fresh);\n    const nextMeta = {\n      user: latest.user || {},\n      revision: latest.revision,\n      effective: Object.assign({}, latest.effective),\n      writable: true,\n    };\n    metaRef.current = nextMeta;\n    setMeta(nextMeta);\n    setSaved(\"\");\n  }\n\n  /** 提交 PUT 并处理响应（save 的内核；guard 占用与释放由 saveFor 负责）。\n   *  409 不再只提示文案——转 handleConflict 进入双动作恢复流程。\n   *  实测补强（浏览器验证发现）：fetch 在极端环境（连接池耗尽/服务端静默\n   *  挂起）可能永不 settle → finally 永不执行 → 按钮永久「保存中」。加 15s\n   *  AbortController 超时兜底：超时中断请求（服务端写入与否未知，UI 必须恢复），\n   *  释放 guard 并提示重试。 */\n  function putAndCommit(payload: Record<string, unknown>, entry: string) {\n    const expectedRevision =\n      metaRef.current && typeof metaRef.current.revision === \"number\"\n        ? metaRef.current.revision\n        : undefined;\n    const ctrl: AbortController | null =\n      typeof AbortController !== \"undefined\" ? new AbortController() : null;\n    const timer: ReturnType<typeof setTimeout> | null = ctrl\n      ? setTimeout(function () {\n          ctrl!.abort();\n        }, 15000)\n      : null;\n    let chain = fetch(ROUTES.config, {\n      method: \"PUT\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify({ patch: payload, expectedRevision: expectedRevision }),\n      signal: ctrl ? ctrl.signal : undefined,\n    })\n      .then(function (r: Response) {\n        return r.json().then(function (body: PutResult) {\n          if (!r.ok) {\n            const nested = body.error;\n            const detail =\n              typeof nested === \"object\" && nested !== null\n                ? nested.details || nested.error\n                : undefined;\n            // 挂 code 供 catch 按契约分流：409 判定优先\n            // err.code === \"SETTINGS_CONFLICT\"，不再依赖错误文案中文匹配\n            // （文案是本地化/可改的，code 是契约字段）。文案保留进 message。\n            // markHttpFailure 两种形状都取：SETTINGS_CONFLICT 在 `body.error.code`，\n            // 围栏拒答的 code 与 error 平铺（它同时补上 status，供失败判定用）。\n            const code = typeof nested === \"object\" && nested !== null ? nested.code : undefined;\n            throw markHttpFailure(new Error(detail || code || \"HTTP \" + r.status), r.status, body);\n          }\n          return body;\n        });\n      })\n      .then(function (body: PutResult) {\n        // 事务性基线推进：只并入本次 PUT 实际提交的 payload\n        // 键——若并入点击后的 settings 全量，在途期间的编辑会被固化为基线而丢失；\n        // 键级并入后，在途新编辑（非 payload 键）仍在 diff 中，由 trailing 补发提交。\n        // 只并入本次 PUT 的 payload 键（在途编辑不固化，语义保留）；合并后再过规范形\n        // （#912 症状3：save 合并后基线仍干净，strip 形态的 payload 与规范基线同构）。\n        baselineRef.current = snapshotBaseline(\n          Object.assign({}, baselineRef.current || {}, payload),\n        ) as SettingsView;\n        const nextMeta = {\n          user: (body && body.user) || {},\n          revision: (body && body.revision) || undefined,\n          effective: Object.assign({}, baselineRef.current),\n          writable: true,\n        };\n        metaRef.current = nextMeta; // 同步写 ref：补发立即读新 revision，不再 409\n        setMeta(nextMeta);\n        setConflict(null); // 覆盖保存成功：横幅关闭（若曾因再 409 重现）\n        setSaved(t(\"savedOk\"));\n        setTimeout(function () {\n          setSaved(\"\");\n        }, 2200);\n      })\n      .catch(function (e: unknown) {\n        const failure = apiFailureOf(e, t);\n        const errCode = e instanceof Error ? (e as HttpFailure).code : undefined;\n        // 409 判定：code 契约优先，中文文案仅作旧服务端回退\n        if (errCode === \"SETTINGS_CONFLICT\" || failure.message.indexOf(\"版本冲突\") >= 0) {\n          // 版本冲突：进入双动作恢复（不再仅提示手动关闭重开）\n          handleConflict(entry);\n          return;\n        }\n        // AbortError（15s 超时兜底）：服务端可能已写入也可能未写入——提示重试，\n        // 用户重试时 revision 若已推进会自然走 409 恢复流程，语义自洽。\n        if (e instanceof Error && e.name === \"AbortError\") {\n          setSaved(t(\"saveTimeout\"), true);\n          return;\n        }\n        setSaved(t(\"saveFail\", { msg: failure.message }), true);\n      });\n    if (timer !== null) {\n      chain = chain.finally(function () {\n        clearTimeout(timer!);\n      });\n    }\n    return chain;\n  }\n\n  /** 从全量 diff 中按入口过滤出本次要提交的键（域保存；\n   *  纯逻辑收敛在模块级 domainPayload，供测试直测）。 */\n  function diffPayloadFor(entry: string): Record<string, unknown> {\n    return domainPayload(diffPayload(), entry);\n  }\n\n  /** 保存（串行 guard 接入，入口参数化）：同一时刻仅一个在途 PUT——\n   *  - entry：\"all\"（foot 全量）/ \"channels\"（频道 tab 域保存，只提 channels 键）；\n   *  - 在途期间再次点击（任意入口）：guard 记 pending=该入口并立即返回；\n   *    本次在途结束（finally 释放 guard）后按被拒入口原样补发（trailing）——\n   *    补发读 settingsRef 最新草稿 + metaRef 最新 revision，无丢失、无误 409，\n   *    域保存被拒不会升级成全量提交（事件 tab 半成品不被误提交）；\n   *  - 空 diff：初次点击提示「未修改」；补发路径（quietIfEmpty=true）静默返回，\n   *    不覆盖刚显示的「已保存」；\n   *  - guard.end() 放 finally：成功/失败/异常任何路径都释放，防按钮永久卡死。 */\n  function saveFor(entry: string, quietIfEmpty?: boolean) {\n    if (!saveGuard.tryBegin(entry)) return; // 在途：记 pending=entry，由在途 finally 补发\n    let payload: Record<string, unknown>;\n    try {\n      payload = diffPayloadFor(entry);\n    } catch (error) {\n      // 防御：tryBegin 后同步异常（diff 计算等理论不可达路径）必须释放 guard\n      saveGuard.end();\n      const detail = error instanceof Error ? error.message : undefined;\n      setSaved(t(\"saveFail\", { msg: String(detail || error) }), true);\n      return;\n    }\n    if (Object.keys(payload).length === 0) {\n      saveGuard.end();\n      if (!quietIfEmpty) setSaved(t(\"unchanged\"));\n      return;\n    }\n    setSaving(true);\n    // 显式标注不等待：putAndCommit 内部已按契约分流处理失败（409 → handleConflict、\n    // 超时 / 其它 → setSaved 提示），它的返回链不会以拒绝收场；此处只补收尾的 UI 复位。\n    void putAndCommit(payload, entry).finally(function () {\n      setSaving(false);\n      const nextEntry = saveGuard.end();\n      if (nextEntry !== null) saveFor(nextEntry, true); // trailing 补发（同入口，天然不循环）\n    });\n  }\n\n  /** 冲突横幅「加载最新」：丢弃本地草稿，切到服务端最新（等价旧「关闭重开」\n   *  的手动重拉，无需用户手动操作）。 */\n  function resolveConflictLoadLatest() {\n    if (!conflict) return;\n    applyLatestQuiet(conflict.latest);\n    setConflict(null);\n    toast(t(\"conflictLoadedLatest\"));\n  }\n\n  /** 冲突横幅「保留我的修改并覆盖」：rebase-then-retry——\n   *  以最新 effective 为新基线，把本地变更键（动作触发时实时重算，非 409 快照，\n   *  横幅期间新编辑不丢）覆盖上去，用新 revision 重提；再 409 会回到横幅\n   *  （每次覆盖消费一次用户动作，天然收敛、无自动风暴）。 */\n  function resolveConflictOverwrite() {\n    if (!conflict) return;\n    const entry = conflict.entry;\n    const latest = conflict.latest;\n    const localChanges = diffPayloadFor(entry); // 实时重算（相对旧基线的当前脏）\n    // 覆盖基线同样收敛（#912 症状3）：rebase 的底与新基线都是快照，横幅期间新编辑不丢。\n    const snapshot = snapshotBaseline(latest.effective || {}) as SettingsView;\n    const merged = rebaseSettings(localChanges, snapshot) as SettingsView;\n    commitSettings(merged); // 同步写 ref：随后 saveFor 立即以 merged 计算 diff\n    baselineRef.current = Object.assign({}, snapshot) as SettingsView;\n    const nextMeta = {\n      user: latest.user || {},\n      revision: latest.revision,\n      effective: Object.assign({}, latest.effective || {}),\n      writable: true,\n    };\n    metaRef.current = nextMeta;\n    setMeta(nextMeta);\n    setConflict(null);\n    setSaved(\"\");\n    // 用最新 revision 重提（quiet 补发语义：diff 由合并后的 settings 计算）\n    saveFor(entry, true);\n  }\n\n  /** 放弃更改——草稿回写加载基线（编辑态/运行时镜像同步还原）。\n   *  经 patch 统一写入口（settingsRef 同步）；按钮在 saving 期间禁用\n   *  （foot 渲染处），消除「在途成功回调覆盖放弃后基线」的竞态。\n   *  放弃即退出冲突语境：409 横幅一并关闭（否则横幅会指向已被丢弃的草稿）。 */\n  function discardChanges() {\n    if (baselineRef.current) {\n      // 放弃即回到基线快照（#912 症状3）：基线恒为规范形，恢复的草稿天然干净。\n      commitSettings(\n        snapshotBaseline(baselineRef.current as unknown as Record<string, unknown>) as SettingsView,\n      );\n    }\n    setConflict(null);\n    setSaved(\"\");\n    toast(t(\"discardOk\"));\n  }\n\n  /**\n   * 发送测试通知（channelId 可选——per-channel 测试；完成后等终态再刷新状态行）。\n   *\n   * POST /test 只承诺已受理（#912 症状2次因）：per-channel 测试走有限轮询等该频道的新终态\n   * （判定与预算见 settings/status-poll.ts），收敛或耗尽后应用最后所见并刷新历史——skipped\n   * 的原因只在历史里，状态行经它直达（statusText 的 history 形参）。全频道广播不定项等待某\n   * 一条，沿用单次刷新。轮询全程只读 GET（不重发 POST，不撞 1 秒节流窗）；读失败保留旧态\n   * （轮询内吞，null 不应用——瞬时抖动不丢已展示的终态）。\n   */\n  /**\n   * 发送测试通知：channelId 给出即 dry-run（测眼前草稿，独立结果态，不触发 poll / loadStatus，\n   * 通过不自动保存）；省略即老路广播（已保存配置，单次刷新）。并发重复点击会重复外发——\n   * 服务端并发帽为 2，超限回 429 提示手动重试（见面板声明与服务端 B5）。\n   */\n  function sendTest(channelId?: string) {\n    if (channelId !== undefined) {\n      const draftChannels =\n        ((settingsRef.current || settings || {}) as SettingsView).channels || [];\n      setDryRun({ channelId: channelId, pending: true });\n      sendTestReq(channelId, draftChannels)\n        .then(function (data) {\n          const status = typeof data.status === \"string\" ? data.status : \"failed\";\n          setDryRun({\n            channelId: channelId,\n            pending: false,\n            status: status,\n            reason: dryRunReasonText(status, data.reason, t, data.soundWarning),\n          });\n        })\n        .catch(function (error: unknown) {\n          const failure = apiFailureOf(error, t);\n          // 请求层失败（400 / 408 / 429 / 中断）：同样落独立结果行，不进 poll，不碰状态行。\n          setDryRun({\n            channelId: channelId,\n            pending: false,\n            status: \"request-failed\",\n            // 本地化前缀 + 英文原文（#1016 残留 4）：直接写 `failure.message` 时这一行整句是英文，\n            // 与紧邻的 toast 两处英文。形态照抄上面那行 toast 的 `testFail`——`{msg}` 留宿主原话供排查。\n            reason: t(\"testRequestFail\", { msg: failure.message, hint: failure.hint }),\n          });\n          toast(t(\"testFail\", { msg: failure.message, hint: failure.hint }));\n        });\n      return;\n    }\n    sendTestReq(channelId)\n      .then(function (data) {\n        toast(\n          t(\n            channelId ? \"testChannelOk\" : \"testSent\",\n            channelId ? undefined : { n: data && data.sseConnections },\n          ),\n        );\n        if (channelId === undefined) {\n          loadStatus({ value: true });\n          return;\n        }\n        const prev = statusRef.current[channelId];\n        const prevTs = prev && typeof prev.lastTs === \"number\" ? prev.lastTs : undefined;\n        void pollChannelStatus(fetchStatus, channelId, prevTs).then(function (result) {\n          if (result.map !== null) {\n            statusRef.current = result.map;\n            setStatusMap(result.map);\n          }\n          loadHistory({ value: true });\n        });\n      })\n      .catch(function (error: unknown) {\n        const failure = apiFailureOf(error, t);\n        toast(t(\"testFail\", { msg: failure.message, hint: failure.hint }));\n      });\n  }\n\n  /** 权限行的授权动作：手势内请求权限，完成后刷新状态行。\n   *  为什么留在卡片这层：requestPermission 的手势内调用与 setSaved/setPermTick 都是本组件的\n   *  闭包，诊断原子只收这一个回调，不反向读本组件状态。 */\n  function requestNotificationPermission() {\n    requestPermission(function () {\n      setSaved(t(\"permRequested\"));\n      setPermTick(permTick + 1); // 触发重渲染刷新权限状态行\n    });\n  }\n\n  // ---- 频道编辑（settings.channels 不可变操作；deviceKey 掩码语义见服务端）----\n\n  /** 更新第 idx 个频道实例（字段经 assignChannelFields 合并——空串/undefined\n   *  写成 null 即显式删除；函数式基于最新 channels，防后写覆盖）。 */\n  function chPatch(idx: number, part: Record<string, unknown>) {\n    patch(function (prev) {\n      const list = (prev.channels || []).slice();\n      // 合并结果恒为频道字段集（assignChannelFields 只做「空值写 null」/浅覆盖，见 settings/diff.ts）。\n      list[idx] = assignChannelFields(list[idx] || {}, part) as SettingsChannelView;\n      return Object.assign({}, prev, { channels: list });\n    });\n  }\n\n  /** 写/删某实例的 levels 映射（kind→level）。\n   *\n   * 这里是**两个方向相反的手势**，别看成同一件事：\n   *  - 删**单个 kind**（`level` 为空）：`delete levels[kind]`。`levels` 是一个键、值是整张映射，\n   *    它的内容由这次提交整个替换，删一个 kind 是「这张表少一项」，走不到「删键」那一层。\n   *  - 清空**整个 levels**（映射被删空）：写 `null` 而不是删键。服务端按字段合并，键缺席读成\n   *    「不动」，删键会让磁盘上那张旧映射原封不动留下来——用户明明清空了它。\n   */\n  function chLevelsSet(idx: number, kind: string, level: string) {\n    if (!kind || kind === \"__proto__\" || kind === \"constructor\" || kind === \"prototype\") return;\n    patch(function (prev) {\n      const list = (prev.channels || []).slice();\n      const ch = Object.assign({}, list[idx]);\n      const levels = Object.assign({}, ch.levels || {});\n      if (level) levels[kind] = level;\n      else delete levels[kind];\n      if (Object.keys(levels).length === 0) ch.levels = null;\n      else ch.levels = levels;\n      list[idx] = ch;\n      return Object.assign({}, prev, { channels: list });\n    });\n  }\n\n  /** 删除第 idx 个频道实例（函数式基于最新 channels）。 */\n  function chRemove(idx: number) {\n    patch(function (prev) {\n      const list = (prev.channels || []).slice();\n      list.splice(idx, 1);\n      return Object.assign({}, prev, { channels: list });\n    });\n  }\n\n  /** 新增频道实例（kind = \"bark\" | \"webhook\"）——自动分配未占用的 id\n   *  （bark-1… / webhook-1…），默认禁用（出站授权显式授予）。可选认证/\n   *  凭据/模板字段一律**不预置键**——空串形态会被服务端写面校验整组 400（token/\n   *  username/password/headerValue 要求非空、headerName 过头名正则），未填写 =\n   *  键不存在；输入清空经 assignChannelFields 写成 null（显式删除）。\n   *\n   *  `url` / `baseUrl` 是**唯一两个不预置的必填键**：它们同样不预置空串占位，而是压根\n   *  没有这个键——必填键传空值会被写面以「必填键，不能删除」400 拒掉，而「没填」本就该由\n   *  服务端以「缺少 url」拒（同一件事的两种说法，后者说的是「你还没填」）。未填即保存：400。\n   *  超时缺省 10s 由服务端 normalize 兜底。 */\n  function chAdd(kind: string) {\n    patch(function (prev) {\n      const list = prev.channels || [];\n      let seq = 1;\n      const taken = new Set(\n        list.map(function (c) {\n          return String(c.id);\n        }),\n      );\n      while (taken.has(kind + \"-\" + seq)) seq += 1;\n      const id = kind + \"-\" + seq;\n      const base: SettingsChannelView =\n        kind === \"webhook\"\n          ? {\n              id: id,\n              name: t(\"chNewWebhookName\") + \" \" + seq,\n              type: \"webhook\",\n              auth: \"none\",\n              timeoutSec: 10,\n              enabled: false,\n            }\n          : {\n              id: id,\n              name: t(\"chNewBarkName\") + \" \" + seq,\n              type: \"bark\",\n              enabled: false,\n            };\n      return Object.assign({}, prev, { channels: list.concat([base]) });\n    });\n    setDelArmedId(null);\n  }\n\n  // ---- 路由（kindRoutes 单源；事件行与频道卡双向编辑同一份配置）----\n\n  /** 当前 kind 的路由数组（undefined = 跟随默认广播）。 */\n  function routeOf(kind: string): string[] | undefined {\n    const routes: Record<string, string[]> = settings?.kindRoutes || {};\n    return routes[kind];\n  }\n\n  /** 写/清 kind 路由条目（ids=null 删除条目恢复默认；函数式基于最新 kindRoutes）。\n   *\n   * 这里是**顶层键**，没有按键合并那回事：`kindRoutes` 整值替换，删条目就是 `delete`，\n   *  **不能**改成写 `null`——顶层值域要求每项是 `string[]`，`null` 会被 `validateKindRoutes`\n   *  拒（「null 需要字符串数组」），而整值替换下 `delete` 本来就是正确的那一支。\n   *  与频道条目里的 `chLevelsSet` 方向相反，别混。 */\n  function routeSetKind(kind: string, ids: string[] | null) {\n    patch(function (prev) {\n      const routes = Object.assign({}, prev.kindRoutes || {});\n      if (ids === null || ids.length === 0) delete routes[kind];\n      else routes[kind] = ids;\n      return Object.assign({}, prev, { kindRoutes: routes });\n    });\n  }\n\n  /** 频道显示名：内置用固定文案（它们的 name 不参与配置），实例用 name 回退 id。 */\n  function channelLabel(c: SettingsChannelView): string {\n    if (c.type === \"browser\") return t(\"chBrowserNotify\");\n    if (c.type === \"system\") return t(\"chSystemNotify\");\n    return c.name || String(c.id);\n  }\n\n  /** 当前「跟随默认」投递面（路由 id 列表）：内置与实例同一判据——`enabled`（发不发）。\n   *  chips 点亮态（无条目时）与首次切换物化的快照都以本函数为准——所见即所得。 */\n  function defaultRouteIds(prev: SettingsView): string[] {\n    const ids: string[] = [];\n    (prev.channels || []).forEach(function (c) {\n      if (c.enabled === true) ids.push(channelIdOf(c));\n    });\n    return ids;\n  }\n\n  /** 路由候选（含停用频道——保留显示以呈现「已配置但未启用」；未启用者置灰\n   *  禁点——投递面 = 启用频道 ∩ 路由，未启用频道即使点亮也不投递，假点亮误导。\n   *  enabled 标志供 chips 置灰/title 提示；已勾选未启用频道不自动清除，\n   *  用户启用后即恢复有效）。候选顺序即 `channels` 顺序：内置恒在最前。 */\n  function routeOptions(\n    prev: SettingsView,\n  ): Array<{ id: string; label: string; enabled: boolean }> {\n    return (prev.channels || []).map(function (c) {\n      return { id: channelIdOf(c), label: channelLabel(c), enabled: c.enabled === true };\n    });\n  }\n\n  /**\n   * 路由 chips 单点切换（chips 直点形态；函数式基于最新\n   * kindRoutes/channels 计算，防同帧勾选后写覆盖）。\n   *\n   * 语义（替代旧「undefined=全选快照」歧义）：\n   * - kindRoutes 无条目 = 跟随默认（投递到全部当前启用频道，随启停动态变化）；\n   * - 任一 chip 切换即把当前默认投递面物化为显式快照（冻结），此后启停变化需显式维护；\n   * - 清空（全灭）= 删除条目恢复跟随默认（与旧实现「空数组即 delete」一致）。\n   */\n  function routeToggle(kind: string, oid: string, checked: boolean) {\n    patch(function (prev) {\n      const routes: Record<string, string[]> = Object.assign({}, prev.kindRoutes || {});\n      const prior = routes[kind];\n      const cur = prior === undefined ? defaultRouteIds(prev).slice() : prior.slice();\n      const at = cur.indexOf(oid);\n      if (checked && at === -1) cur.push(oid);\n      else if (!checked && at !== -1) cur.splice(at, 1);\n      if (cur.length === 0) delete routes[kind];\n      else routes[kind] = cur;\n      return Object.assign({}, prev, { kindRoutes: routes });\n    });\n  }\n\n  /** 动态 kind 确认（POST /kinds；完成后刷新清单并提示）。\n   *  响应体带新 revision → 同步 metaRef/setMeta——服务端\n   *  确认写入已推进 revision，若不同步，同一窗口随后保存会带过期 revision 必 409\n   *  （无并发的纯版本链断点，比连点更高频）。 */\n  function confirmOne(kind: string, confirmed: boolean) {\n    postKind(kind, confirmed)\n      .then(function (body) {\n        const freshRevision = body && typeof body.revision === \"number\" ? body.revision : undefined;\n        if (freshRevision !== undefined && metaRef.current) {\n          const nextMeta = Object.assign({}, metaRef.current, { revision: freshRevision });\n          metaRef.current = nextMeta;\n          setMeta(nextMeta);\n        }\n        toast(t(\"kindConfirmOk\"));\n        return loadKinds({ value: true });\n      })\n      .catch(function (e: unknown) {\n        const detail = e instanceof Error ? e.message : undefined;\n        toast(t(\"kindConfirmFail\", { msg: detail || e }));\n      });\n  }\n\n  function confirmClear() {\n    if (!clearArmedValue) {\n      setClearArmed(true);\n      setTimeout(function () {\n        setClearArmed(false);\n      }, 3000);\n      return;\n    }\n    setClearArmed(false);\n    fetch(ROUTES.history, { method: \"DELETE\" })\n      .then(function (r: Response) {\n        // 只挂响应码、不读响应体：DELETE 的失败体未必是 JSON，解析它会把一条失败请求\n        // 变成两条（读体再抛）。状态码足以让判定侧不再依赖「文案里含 403」这条兜底。\n        if (!r.ok) throw markHttpFailure(new Error(\"HTTP \" + r.status), r.status);\n        return r.json();\n      })\n      .then(function (data: ClearHistoryResult) {\n        toast(t(\"cleared\", { n: data.removed || 0 }));\n        loadHistory({ value: true });\n      })\n      .catch(function (error: unknown) {\n        const failure = apiFailureOf(error, t);\n        toast(t(\"clearFail\", { msg: failure.message, hint: failure.hint }));\n      });\n  }\n\n  /**\n   * 事件/动态 kind 行的路由区（chips 直点形态）：\n   * 候选 chips（点亮态真实反映投递面：无条目=defaultRouteIds，有条目=显式快照）\n   * + stale 残留 chip（虚线删除线，title 说明）+ 状态标签（跟随默认 / 自定义·N·恢复默认）。\n   * 状态标签 custom 态可点击恢复跟随默认；全灭由 routeToggle 自动恢复默认并 toast 反馈\n   * 由调用方无感（删除条目即恢复——状态标签随即回到默认态）。\n   */\n  function routeChipsRow(kind: string) {\n    const routes = routeOf(kind);\n    // 本函数只在 settings 已加载的渲染路径被调用（651 行守卫之后）；`?? {}` 只是让\n    // 嵌套函数体内丢失的 narrowing 仍有定义（该分支不可达，原先是直接读 null 抛错）。\n    const options = routeOptions(settings ?? {});\n    const litIds = routes === undefined ? defaultRouteIds(settings ?? {}) : routes.slice();\n    const litSet: Record<string, boolean> = {};\n    litIds.forEach(function (id: string) {\n      litSet[id] = true;\n    });\n    // stale：条目残留但候选中不存在的频道 id（已删除频道；投递时自动跳过，保存时清理）\n    const staleIds = (routes || []).filter(function (id: string) {\n      return !options.some(function (o) {\n        return o.id === id;\n      });\n    });\n    const chips = options.map(function (o) {\n      const on = litSet[o.id] === true;\n      // 未启用频道：置灰禁点——投递面 = 启用频道 ∩ 路由，停用频道点亮\n      // 也不投递（假点亮）；title 说明「启用后可用」。已勾选未启用项保留勾选\n      // 显示（不自动改用户配置），用户启用频道后该 chip 恢复可点/生效。\n      return (\n        <button\n          type=\"button\"\n          key={o.id}\n          className={\"dn-route-chip\" + (on ? \" is-on\" : \"\") + (o.enabled ? \"\" : \" is-off\")}\n          aria-pressed={on ? \"true\" : \"false\"}\n          disabled={!o.enabled}\n          title={o.enabled ? undefined : t(\"routeDisabledHint\")}\n          onClick={function () {\n            routeToggle(kind, o.id, !on);\n          }}\n        >\n          {o.label}\n        </button>\n      );\n    });\n    staleIds.forEach(function (id: string) {\n      chips.push(\n        <span key={\"stale-\" + id} className=\"dn-route-chip is-stale\" title={t(\"routeStaleTitle\")}>\n          {id + \" · \" + t(\"routeStaleChip\")}\n        </span>,\n      );\n    });\n    const isCustom = routes !== undefined;\n    chips.push(\n      <button\n        type=\"button\"\n        key=\"state\"\n        className={\"dn-route-state\" + (isCustom ? \" is-custom\" : \"\")}\n        title={isCustom ? t(\"routeCustomStateTitle\") : t(\"routeDefaultStateTitle\")}\n        onClick={function () {\n          if (isCustom) routeSetKind(kind, null);\n        }}\n      >\n        {isCustom\n          ? t(\"routeCustomState\", { n: litIds.length - staleIds.length })\n          : t(\"routeDefaultState\")}\n      </button>,\n    );\n    // 默认收成投递摘要；自定义但候选无点亮（仅 stale 残留等）不得误报「跟随默认」\n    // 摘要点名的是真实投递面（启用 ∩ 点亮）：停用频道即使在快照里点亮也不投递，\n    // 点名它即假点亮（M1）。N 取快照内现存候选数（剔除已删频道的 stale 残留，\n    // stale 在展开区以独立 chip 呈现，不重复计入 N）。决策函数见 parts/route-text.ts。\n    const litLabels: string[] = [];\n    options.forEach(function (o) {\n      if (o.enabled && litSet[o.id] === true) litLabels.push(o.label);\n    });\n    const summaryText = routeSummaryText(litLabels, isCustom, litIds.length - staleIds.length, t);\n    return (\n      <details className=\"dn-evt-routeDisc\" key={\"routes-\" + kind}>\n        <summary className=\"dn-evt-routeSum\" title={t(\"routeExpandHint\")}>\n          {summaryText}\n        </summary>\n        <div className=\"dn-evt-routes\">\n          <span className=\"dn-evt-routesCap\">{t(\"routeCap\")}</span>\n          {chips}\n        </div>\n      </details>\n    );\n  }\n\n  // 能力自检的渲染模型：宿主面（读服务端载荷）+ 浏览器面（读本页事实）合成一次，\n  // 下面所有卡片只投影它——JSX 里不再出现任何「这个状态算不算好」的判断。\n  const diag = clientDiagnosticsOf(diagnostics, clientFacts(), t);\n\n  // 三端降级文案（浏览器通知权限状态行已移入「浏览器通知」频道卡，\n  // 这里只保留服务不可用 / 非安全上下文 / 平台不支持三条全局降级说明）\n  const degradation = degradationNotes(metaValue, t, isSecureContext);\n\n  // ---- 卡内三 tab（通知事件 / 通知频道 / 通知记录）----\n\n  // 待确认动态 kind 计数（「通知事件」tab 徽标——确认流是安全设计，不可被 tab 埋没）\n  const pendingKinds = kindsList.filter(function (k) {\n    return !k.confirmed;\n  }).length;\n\n  // tab 栏：三个普通 button（不引入 role=tablist 管理成本）+ 分段 icon\n  const tabbar = tabBar(activeTab, pendingKinds, t, setActiveTab);\n\n  // 去掉设置卡 title/副标题；顶部直接是 tab 栏。\n  // 底部保存栏 = 脏状态指示（diffSettingsPayload 键数）+ 放弃更改 + 保存。\n  // foot 显示全量脏计数（含频道域）；「保存频道」按钮的域脏态不做单独\n  // 计数——无频道域脏时点击走空 diff 的「未修改」提示（与 foot 保存同交互语义）。\n  const dirtyCount = Object.keys(diffPayload()).length;\n  // 频道域脏：domainPayload(\"channels\") 是顶层单键负载（{} 或 {channels}），\n  // Object.keys 长度只能 0/1——文案按「域是否脏」说，不假装能数出 N 处频道字段。\n  const channelsDiff = diffPayloadFor(\"channels\");\n  const channelsDirty = Object.keys(channelsDiff).length > 0;\n  const channelsDirtyCount = channelsDirty ? 1 : 0;\n  const otherDirtyCount = Math.max(0, dirtyCount - channelsDirtyCount);\n  // 脏文案决策见 parts/route-text.ts（M2：可执行断言覆盖三分支）。\n  const dirtyText = dirtyStatusText(dirtyCount, channelsDirty, otherDirtyCount, t);\n\n  /**\n   * dry-run 结果行（B-S1-4）：独立行、打标「草稿测试·未落盘」，常驻 [去保存][放弃草稿]，\n   * 通过不自动保存。state 在卡片顶层：切 tab 保留（B8），改草稿即清（patch/commitSettings）。\n   */\n  const dryRunRow = dryRunRowOf(\n    dryRun,\n    saving,\n    t,\n    function () {\n      saveFor(\"channels\");\n    },\n    discardChanges,\n  );\n\n  // 三个 pane 的**条件调用**（普通函数返回 JSX，非 active tab 根本不调用——保持既有条件渲染\n  // 语义；改成组件会引入挂载/卸载）。依赖一律显式传参，pane 模块内不读本组件闭包。\n  // 频道 tab 的依赖面（三张卡的并集）以单一对象传入：位置参数会退化成 25 项长表。\n  const channelsPaneDeps = {\n    settings,\n    statusMap,\n    history,\n    hostPlatform,\n    diag,\n    channelLabel,\n    chPatch,\n    chRemove,\n    chLevelsSet,\n    chAdd,\n    sendTest,\n    isSecureContext,\n    requestNotificationPermission,\n    audioEngine,\n    kindsList,\n    delArmedId,\n    setDelArmedId,\n    levelsNew,\n    setLevelsNew,\n    revealMap,\n    setRevealMap,\n    secretEdited,\n    markSecretEdited,\n    saving,\n    saveFor,\n    testDirty: channelsDirty,\n    t,\n  };\n  return (\n    <li className=\"dn-set-card\">\n      {tabbar}\n      <div className=\"dn-set-body\">\n        {dryRunRow}\n        {/* 历史独立成 tab：清理/发送测试/刷新并排工具行；请求权限按钮随权限状态行归入\n            「浏览器通知」频道卡 */}\n        {activePaneOf(activeTab, {\n          events: function () {\n            return eventsPane(settings, kindsList, patch, confirmOne, routeChipsRow, severityOf, t);\n          },\n          channels: function () {\n            return channelsPane(channelsPaneDeps);\n          },\n          history: function () {\n            return historyPane(\n              history,\n              clearArmedValue,\n              confirmClear,\n              sendTest,\n              loadHistory,\n              severityOf,\n              t,\n            );\n          },\n        })}\n        <div className=\"dn-set-notes\">{degradation}</div>\n        {/* 409 冲突双动作横幅（非模态：横幅期间可继续编辑；动作触发时\n              实时重算本地变更）。「忽略」= 关闭横幅、草稿保留原样。 */}\n        {conflictBanner(\n          conflict,\n          saving,\n          t,\n          resolveConflictLoadLatest,\n          resolveConflictOverwrite,\n          function () {\n            setConflict(null);\n          },\n        )}\n        <div className=\"dn-set-foot\">\n          {saveStatusNode(saved, dirtyText)}\n          <span className=\"dn-spacer\" />\n          {/* 保存中（guard 在途）禁用「放弃更改」与「保存」——防提交窗口内矛盾操作\n                （放弃被在途成功回调覆盖基线）与连点重复 PUT；按钮文案切换「保存中…」。 */}\n          <button\n            type=\"button\"\n            className=\"dn-set-btn dn-set-btnSmall\"\n            disabled={saving}\n            onClick={discardChanges}\n          >\n            {t(\"discardChanges\")}\n          </button>\n          <button\n            type=\"button\"\n            className=\"dn-set-save\"\n            disabled={saving}\n            onClick={function () {\n              saveFor(\"all\");\n            }}\n          >\n            {saving ? t(\"saving\") : t(\"save\")}\n          </button>\n        </div>\n      </div>\n    </li>\n  );\n}\n\n// ------------------------------------------------------------ 装配\n\n/**\n * 页面级单例的归属令牌容器：每次 apply 换一枚新令牌，清理时先比对。热更或重复 apply 时旧实例\n * 的 disposer 仍会执行，无条件清理会把新实例正在用的 <style> / 标题闪烁 / 弹窗一并摘掉。\n */\nconst pageOwner: { current: object | null } = { current: null };\n\n/**\n * 宿主 locale 服务读形态：官方 LocaleRuntime 的最小面（本包只用 register/bind/subscribe/\n * getSnapshot；缺失即回落 key 本体）。Pick 派生而非手抄签名——register 的字典类型因此\n * 直接受官方 LocaleDictOf 收口（漏键/多键编译期判红）。官方 register 返回 disposer，本包\n * 沿用既有调用行为照旧不接返回值（不新增生命周期逻辑）。\n */\ntype LocaleServiceView = Pick<LocaleRuntime, \"register\" | \"bind\" | \"subscribe\" | \"getSnapshot\">;\n\n/**\n * 宿主插槽读形态：官方 SlotRegistry 的最小面（本包只用 settings.section 的 inject/register；\n * 缺失即 tab 不挂载）。inject 的 key 面由官方 SlotMap 收口，register 的选项面由官方\n * SlotCore 收口——宿主改签名/改槽位声明即判红。\n */\ntype SlotsView = Pick<SlotRegistry, \"inject\" | \"register\">;\n\n/**\n * 浏览器端上下文的窄面（本包实际使用的面：get + effect），与 inject 声明的\n * [\"slots\", \"locale\"] 对齐；slots/locale 各自的读形态见上。effect 面与 DisposerHost\n * 同形（finally 里 stack.attach 直接消费）。\n */\ninterface ClientContext {\n  get: (name: string) => unknown;\n  effect: (callback: () => () => void, id: string) => void;\n}\n\n/**\n * locale 接缝：注册字典 → 绑翻译函数 → 订阅 locale 变化重绑。\n *\n * 与 slots 接线、通知半区是**三处独立的宿主接缝**，各有各的降级口径：这一处失败只回落\n * key 本体（面板照常，只是文案是 key），slots 失败只少一个 tab，通知半区失败才是半区不可用。\n * 三条口径混在 apply 一处时，判红分不清是哪条接缝坏了。\n */\nfunction bindLocaleService(ctx: ClientContext, stack: DisposerStack): void {\n  const locale = ctx.get(\"locale\") as LocaleServiceView | null | undefined;\n  // 订阅取消函数供 disposer 卸载调用（守卫对齐 provider-usage/\n  // mcp-manager 的 undefined 形态——不预设 subscribe 返回 null，防其返回\n  // null 时 null 初始化遮蔽导致守卫失效），防重复 apply 后旧订阅持续重绑\n  // 已停用实例。\n  let unsubLocale: (() => void) | undefined;\n  if (locale && typeof locale.register === \"function\") {\n    // 收窄后的别名：嵌套回调内 narrowing 会重置，别名本身即非空类型，回调内照常可用。\n    const localeService = locale;\n    // bind/subscribe 必须带接收者调用：宿主实现依赖 this，detached 摘出即抛，失败被各层 catch 静默吞掉后整面板回落 key 本体。\n    try {\n      localeService.register(NS, { zh: zh, en: en });\n      // 官方 bind(NS) 命中类型化重载：返回 TranslateNS<'notifier'>，key 面比本包 t 收口的宽\n      // Translate（官方宽面，全文调用点）更窄，收口在适配这一处。断言两端都是官方类型；\n      // 端口本体已是 Pick<LocaleRuntime, …>，上游改 bind/register/subscribe/getSnapshot 仍判红。\n      bindTranslate(localeService.bind(NS) as Translate);\n      if (\n        typeof localeService.subscribe === \"function\" &&\n        typeof localeService.getSnapshot === \"function\"\n      ) {\n        unsubLocale = localeService.subscribe(function () {\n          try {\n            bindTranslate(localeService.bind(NS) as Translate);\n          } catch {\n            /* 忽略 */\n          }\n        });\n      }\n    } catch (e) {\n      console.warn(\"[dsh-notifier] locale 注册失败：\", e);\n    }\n  }\n  if (unsubLocale !== undefined) {\n    const unsubscribe = unsubLocale;\n    stack.own(function () {\n      unsubscribe();\n    });\n  }\n}\n\n/**\n * slots 接缝：把设置面板注册成独立 tab。\n *\n * 参照 dsh-provider-usage「用量统计」tab 的接线（slots.inject + register，独立顶层页）。\n * 旧运行时若不声明该插槽，inject 回调不执行 → tab 不挂载、通知半区照常工作（与\n * provider-usage 同语义，不做 plugin.item 双插槽重复展示）。\n */\nfunction injectSettingsTab(ctx: ClientContext): void {\n  const slots = ctx.get(\"slots\") as SlotsView | null | undefined;\n  if (slots && typeof slots.inject === \"function\") {\n    const slotHost = slots;\n    // 就地兜住插槽接线：这里失败只意味着设置 tab 没挂上，通知半区照常工作；冒到外层会被\n    // 报成整段「挂载失败」，把一次可降级的缺页说成插件不可用。\n    try {\n      slotHost.inject(\"settings.section\", function () {\n        return slotHost.register(\n          // label 传 thunk：宿主 nav rows 每次读取经 resolveSlotLabel\n          // 求值 + shell 订阅 locale 重渲染，切语言即跟随（注册期求值字符串快照是旧行为）。\n          // t 走 client/locale.ts 的当前绑定（locale.subscribe 回调重绑），thunk 保持最小\n          // t(key) 形态、不包任何可能抛错的逻辑（thunk 抛错会炸宿主 nav 渲染）。\n          {\n            name: \"settings.section\",\n            id: \"dsh-notifier\",\n            order: 70,\n            label: () => t(\"tabLabel\"),\n            locale: NS,\n          },\n          function () {\n            return <SettingsCard />;\n          },\n        );\n      });\n    } catch (error) {\n      console.warn(\"[dsh-notifier] 设置 tab 未挂载：\", error);\n    }\n  } else {\n    console.warn(\"[dsh-notifier] 缺少 slots 服务，设置 tab 未挂载（通知半区照常工作）\");\n  }\n}\n\nexport function apply(ctx: ClientContext): void {\n  // 清理栈：边装配边采集 teardown，登记点（attach）放在 finally——中途同步抛错时，\n  // 已建立的那些资源也仍有 disposer 可摘（见 shared/disposers.ts 文件头对登记点在后的说明）。\n  const stack = createDisposerStack();\n  try {\n    // 页面级单例（<style> / 标题闪烁 / 已弹通知）的归属令牌：热更或重复 apply 时旧实例的\n    // disposer 仍会执行，只有仍属当前实例的清理才许动这些共享资源，否则新实例会变成无样式\n    // 页面、丢掉闪烁提示、连带关掉自己正在显示的弹窗。\n    const owner: object = {};\n\n    // 两处**页面级单例**没有「建立时刻」（<style> 由 ensureStyle 复用同 id 元素，通知登记是\n    // 模块级表），故顶格登记；释放是逆序的，排最前 = 最后释放，共享外壳比实例资源活得久。\n    // <style> 只在仍是当前归属者时才摘，否则旧实例的 disposer 会把新实例的样式表摘掉\n    // （页面变成无样式）；摘除即让位，归属随之清空。\n    stack.own(function () {\n      if (pageOwner.current !== owner) return;\n      pageOwner.current = null;\n      document.getElementById(STYLE_ID)?.remove();\n    });\n    stack.own(function () {\n      closeNotificationsOf(owner);\n    });\n\n    // 样式注入后立刻认领页面级归属（就在这一行，不是装配成功之后）：认领的时刻就是「本实例开始\n    // 为这个共享节点负责」的时刻。放到末尾会让半途失败的实例永远不认领，而它刚注入的样式表此后\n    // 再也摘不掉——R5 的漏清理换了个形态复活（登记点有了，释放却被归属判定挡掉）。\n    ensureStyle({ id: STYLE_ID, cssText: UI_CSS + STYLE, version: CSS_VERSION });\n    pageOwner.current = owner;\n\n    // 页面重新可见时：还原标题 + 强制重建 SSE（iOS 后台挂起后连接可能已失效，\n    // 重建自动带 since 补拉，避免断线窗口漏通知）。\n    // 具名 handler 在 apply 内注册、disposer 移除（对齐 mcp-manager\n    // onVisible 范式）——匿名模块体注册无卸载路径，重复 apply/热更会累积旧监听。\n    // 释放是同步的：不存在「监听还在、标题已还原」的窗口（没有谁能在同一个同步循环里派发\n    // 事件），故这里不需要为次序做取舍——逆序释放让实例资源先走、页面级单例最后走。\n    function onVisibilityChange() {\n      if (document.visibilityState === \"visible\") {\n        titleFlasher.restore(owner);\n        eventsHandle.current?.reconnect();\n      }\n    }\n    document.addEventListener(\"visibilitychange\", onVisibilityChange);\n    stack.own(function () {\n      document.removeEventListener(\"visibilitychange\", onVisibilityChange);\n    });\n    // 标题恢复原本只由 visibilitychange 回前台触发；disposer 摘除监听后该路径关闭，\n    // 若残留恢复缓存则标题永久卡在「🔔 …」（复现路径：hidden 帧 → 卸载）。\n    // 带归属：旧实例的 disposer 不许摘掉新实例的闪烁（见 notify/title.ts）。\n    stack.own(function () {\n      titleFlasher.restore(owner);\n    });\n\n    // i18n：注册本插件字典；t 绑定官方 locale 服务（未装配回落 key 本体）。\n    bindLocaleService(ctx, stack);\n\n    // 通知半区（SSE / 浏览器通知）：不依赖任何插件 DOM，直接启动。\n    // 会话是「建立 + 配对释放」的资源，走 acquire：make 抛错就不留释放登记（会话没建成，\n    // 也没有要关的东西）。\n    eventsHandle.current = stack.acquire(\n      function () {\n        return startNotifySession(\n          {\n            url: ROUTES.events,\n            createSource: (url) => new EventSource(url) as unknown as EventSourceLike,\n            now: () => Date.now(),\n            setTimer: (fn, ms) => window.setTimeout(fn, ms),\n            clearTimer: (handle) => {\n              window.clearTimeout(handle);\n            },\n            warn: (message, cause) => {\n              console.warn(\"[dsh-notifier] \" + message + \"：\", cause);\n            },\n          },\n          function (payload) {\n            handleNotifyFrame(payload, owner);\n          },\n        );\n      },\n      function (session) {\n        session.close();\n        // 只在仍指向自己的会话时才清空：重复 apply 时后装的实例才是当前句柄，\n        // 无条件置 null 会让存活实例的回前台重连静默失效（跨实例串味）。\n        if (eventsHandle.current === session) eventsHandle.current = null;\n      },\n    );\n    // 首次任意点击解锁音频（浏览器自动播放策略要求手势）。具名 + disposer 摘除：\n    // 从未点击就被卸载时，匿名监听会永久留在 document 上，且下次点击会在插件已卸载后\n    // 构造一个 AudioContext。\n    function onFirstClick() {\n      audioEngine.unlock();\n      document.removeEventListener(\"click\", onFirstClick, { capture: true });\n    }\n    document.addEventListener(\"click\", onFirstClick, { capture: true });\n    stack.own(function () {\n      document.removeEventListener(\"click\", onFirstClick, { capture: true });\n    });\n\n    // 设置面板独立 tab「通知中心」（settings.section）。\n    // 参照 dsh-provider-usage「用量统计」tab 的接线（slots.inject + register，\n    // 独立顶层页）；label 为导航显示文本。旧运行时若不声明该插槽，inject\n    // 回调不执行 → tab 不挂载、通知半区照常工作（与 provider-usage 同语义，\n    // 不做 plugin.item 双插槽重复展示）。\n    injectSettingsTab(ctx);\n  } catch (error) {\n    console.warn(\"[dsh-notifier] 挂载失败：\", error);\n  } finally {\n    stack.attach(ctx, \"dsh-notifier\", function (error) {\n      console.warn(\"[dsh-notifier] 卸载清理失败：\", error);\n    });\n  }\n}\n\n// ---- 客户端契约：apply/inject 由 build-client 经 factory 装配（干净模块，React externals）----\n// 设置卡片是 React 组件（settings.section 独立 tab 插槽由宿主 React 渲染）；通知半区\n// 不依赖任何 DOM，slot 缺失时照常工作。\nexport const inject: string[] = [\"slots\", \"locale\"];\n"
    },
